'GOV' => [
    ['ref'=>'GOV-01','question'=>'Has the organization established a formal information security policy approved by executive leadership?','guidance'=>'Look for a documented information security policy signed by the CEO, CISO, or board. Verify it has been communicated to all employees and reviewed within the last 12 months.','maturity_1'=>'No formal security policy exists or it is severely outdated.','maturity_2'=>'A security policy exists but may not be comprehensive or regularly reviewed.','maturity_3'=>'Comprehensive security policy is documented, approved by leadership, communicated to all staff, and reviewed annually.','maturity_4'=>'Policy is continuously improved based on threat intelligence and business changes with automated compliance checking.','control_examples'=>'Examples: Written Information Security Policy document, Board minutes showing approval, Email/portal distribution records, Annual review change log.','sort_order'=>1],
    ['ref'=>'GOV-02','question'=>'Are information security roles, responsibilities, and reporting structures clearly defined, including a designated CISO or equivalent?','guidance'=>'Verify there is an organizational chart showing security leadership, a named CISO or equivalent, and documented responsibilities for security staff. Check that the CISO reports to senior leadership.','maturity_1'=>'No dedicated security role exists; security is handled ad hoc by IT staff.','maturity_2'=>'A security lead is designated but lacks formal authority or dedicated team.','maturity_3'=>'CISO or equivalent is appointed with clear authority, dedicated team, and defined reporting to executive leadership.','maturity_4'=>'Security organization is mature with specialized roles, succession planning, and regular capability assessments.','control_examples'=>'Examples: Org chart with CISO position, Job descriptions for security roles, RACI matrix for security functions, Board committee charter.','sort_order'=>2],
    ['ref'=>'GOV-03','question'=>'Does the board or executive leadership receive regular cybersecurity risk briefings and provide strategic direction?','guidance'=>'Check for evidence of board-level cybersecurity reporting at least quarterly. Look for board meeting minutes, risk dashboards, and strategic decisions documented.','maturity_1'=>'Board has no visibility into cybersecurity posture or risks.','maturity_2'=>'Board receives occasional security updates, typically after incidents.','maturity_3'=>'Board receives quarterly cybersecurity briefings with risk metrics, compliance status, and strategic recommendations.','maturity_4'=>'Board actively drives cybersecurity strategy with real-time dashboards, scenario planning, and dedicated cyber committee.','control_examples'=>'Examples: Board meeting minutes with security agenda items, Quarterly CISO board presentation, Risk dashboard screenshots, Board-approved security budget.','sort_order'=>3],
    ['ref'=>'GOV-04','question'=>'Has the organization developed a multi-year cybersecurity strategy and roadmap aligned with business objectives?','guidance'=>'Look for a documented 2-3 year security strategy that ties security initiatives to business goals. Should include milestones, resource requirements, and prioritized projects.','maturity_1'=>'No security strategy exists; actions are purely reactive.','maturity_2'=>'Informal security plans exist but are not aligned with business objectives or funded.','maturity_3'=>'Documented multi-year strategy exists, aligned with business goals, with funded initiatives and quarterly progress tracking.','maturity_4'=>'Strategy is dynamic, continuously updated based on threat landscape, and integrated into enterprise strategic planning.','control_examples'=>'Examples: Security strategy document, Project roadmap with timelines, Budget allocation records, Quarterly progress reports.','sort_order'=>4],
    ['ref'=>'GOV-05','question'=>'Has the organization implemented a formal risk management framework to identify, assess, and treat information security risks?','guidance'=>'Verify the organization uses a recognized risk methodology (NIST RMF, ISO 31000, FAIR). Check for a risk register, risk assessment procedures, and evidence of regular risk reviews.','maturity_1'=>'No formal risk management process exists.','maturity_2'=>'Basic risk assessments are performed but not consistently or with a standard methodology.','maturity_3'=>'Formal risk management framework is implemented with documented methodology, maintained risk register, and regular reviews.','maturity_4'=>'Risk management is quantitative, automated, integrated with business decisions, and continuously updated.','control_examples'=>'Examples: Risk management policy, Risk register with ratings, Risk assessment methodology document, Quarterly risk review meeting minutes.','sort_order'=>5],
    ['ref'=>'GOV-06','question'=>'Does the organization maintain an inventory of applicable regulatory, legal, and contractual security requirements?','guidance'=>'Look for a documented list of all applicable regulations (GDPR, HIPAA, PCI DSS, SOX, etc.), legal obligations, and contractual security requirements. Verify it is reviewed when new contracts or regulations emerge.','maturity_1'=>'No inventory of regulatory requirements exists.','maturity_2'=>'Some regulations are known but not formally tracked or mapped to controls.','maturity_3'=>'Complete inventory maintained with each requirement mapped to controls and assigned owners, reviewed annually.','maturity_4'=>'Automated regulatory change monitoring with impact analysis and proactive control updates.','control_examples'=>'Examples: Regulatory requirements register, Contract security clause tracker, Legal compliance matrix, Regulatory change alerts.','sort_order'=>6],
    ['ref'=>'GOV-07','question'=>'Is there dedicated budget allocation for information security with adequate resources to implement the security program?','guidance'=>'Verify a dedicated security budget exists separate from general IT spending. Check for resource planning, staffing plans, and technology investment documentation.','maturity_1'=>'No dedicated security budget; security spending comes from general IT ad hoc.','maturity_2'=>'Some budget exists but is insufficient and competes with IT operational spending.','maturity_3'=>'Dedicated security budget approved by leadership, aligned with risk priorities, and tracked separately.','maturity_4'=>'Budget is risk-driven, benchmarked against industry peers, with scenario-based funding models.','control_examples'=>'Examples: Annual security budget document, Headcount plan, Technology investment roadmap, Budget vs actual spending reports.','sort_order'=>7],
    ['ref'=>'GOV-08','question'=>'Is there an established security steering committee or governance body with cross-functional representation?','guidance'=>'Look for a governance body that meets regularly with representatives from IT, legal, compliance, HR, and business units. Check meeting minutes and decision records.','maturity_1'=>'No security governance body exists.','maturity_2'=>'Informal meetings occur but without structure, agenda, or documented outcomes.','maturity_3'=>'Formal steering committee meets quarterly with documented charter, cross-functional membership, and tracked action items.','maturity_4'=>'Governance body drives strategic decisions with escalation paths, sub-committees for specific domains, and effectiveness reviews.','control_examples'=>'Examples: Committee charter, Membership roster, Meeting minutes, Decision log, Action item tracker.','sort_order'=>8],
    ['ref'=>'GOV-09','question'=>'Does the organization track and report cybersecurity metrics and KPIs to measure program effectiveness?','guidance'=>'Check for defined security metrics (mean time to detect, patch compliance rate, training completion, etc.) that are regularly reported to management.','maturity_1'=>'No security metrics are tracked.','maturity_2'=>'Some metrics are collected but not consistently reported or acted upon.','maturity_3'=>'Defined KPIs are tracked monthly, reported to leadership, and used to drive improvement initiatives.','maturity_4'=>'Real-time security dashboards with trend analysis, automated alerting on KPI deviations, and predictive analytics.','control_examples'=>'Examples: Monthly security metrics report, KPI dashboard screenshots, Trend analysis charts, Management review meeting minutes.','sort_order'=>9],
    ['ref'=>'GOV-10','question'=>'Has the organization established a code of conduct and ethics policy that addresses information security responsibilities?','guidance'=>'Look for a code of conduct that includes acceptable use of technology, data handling expectations, and consequences for violations. Verify employee acknowledgment records.','maturity_1'=>'No code of conduct exists or it does not address information security.','maturity_2'=>'Code of conduct exists but security expectations are vague or not enforced.','maturity_3'=>'Comprehensive code of conduct with specific security provisions, annual employee acknowledgment, and clear enforcement procedures.','maturity_4'=>'Code is integrated with security awareness, includes scenario-based guidance, and violations are tracked with corrective actions.','control_examples'=>'Examples: Code of conduct document, Employee acknowledgment forms, Violation tracking records, Annual distribution receipts.','sort_order'=>10],
    ['ref'=>'GOV-11','question'=>'Is there a formal process for requesting, reviewing, and approving exceptions to security policies?','guidance'=>'Verify a documented exception process exists with risk-based approval, time-limited exceptions, and compensating controls. Check the exception register.','maturity_1'=>'No exception process exists; policies are bypassed informally.','maturity_2'=>'Exceptions are handled case-by-case without consistent documentation or approval.','maturity_3'=>'Formal exception process with risk assessment, compensating controls, time limits, and management approval documented.','maturity_4'=>'Exception data feeds into policy improvement, automated expiration tracking, and trend analysis to identify systemic issues.','control_examples'=>'Examples: Exception request form template, Exception register with approvals, Compensating control documentation, Expiration tracking log.','sort_order'=>11],
    ['ref'=>'GOV-12','question'=>'Is information security integrated into business processes, project management, and organizational change management?','guidance'=>'Check that security is considered in new projects, business changes, and process designs. Look for security gates in project lifecycle and change management procedures.','maturity_1'=>'Security is not considered in business processes or projects.','maturity_2'=>'Security is occasionally consulted for major projects but not systematically.','maturity_3'=>'Security review is a required gate in project lifecycle, change management includes security impact analysis.','maturity_4'=>'Security is embedded in all business processes with automated security assessment tools integrated into DevOps and change workflows.','control_examples'=>'Examples: Project security review checklist, Change management security impact assessment form, Security gate sign-off records, DevSecOps pipeline evidence.','sort_order'=>12],
],

// =========================================================================
// IAM - Identity & Access Management (14 questions)
