'IAM' => [
    ['ref'=>'IAM-01','question'=>'Does the organization have a formal process for provisioning and deprovisioning user accounts across all systems?','guidance'=>'Verify documented procedures for creating accounts when employees join and disabling/deleting accounts when they leave. Check for automated HR-to-IT integration and timely access removal.','maturity_1'=>'Account creation and removal is manual and inconsistent with no formal process.','maturity_2'=>'Basic procedures exist but rely on manual requests and may have delays in deprovisioning.','maturity_3'=>'Automated provisioning/deprovisioning integrated with HR systems, SLA for access removal within 24 hours of termination.','maturity_4'=>'Fully automated identity lifecycle with real-time HR integration, automated access removal, and continuous reconciliation.','control_examples'=>'Examples: Account provisioning procedure, HR-IT integration workflow, Terminated user access removal logs, Account reconciliation reports.','sort_order'=>1],
    ['ref'=>'IAM-02','question'=>'Is the principle of least privilege enforced, ensuring users only have access necessary for their job functions?','guidance'=>'Check that access is granted based on job requirements, not inherited from previous roles. Look for role definitions, access matrices, and evidence that excessive privileges are identified and removed.','maturity_1'=>'No least privilege enforcement; users accumulate access over time without review.','maturity_2'=>'Least privilege is a policy but not consistently enforced; privilege creep is common.','maturity_3'=>'Access is granted based on defined roles, periodic reviews catch excessive access, and privilege requests require justification.','maturity_4'=>'Just-in-time access provisioning, automated privilege analysis, and continuous enforcement with anomaly detection.','control_examples'=>'Examples: Role-based access matrix, Access request approval records, Privilege review reports, Account audit showing no excessive access.','sort_order'=>2],
    ['ref'=>'IAM-03','question'=>'Is multi-factor authentication (MFA) implemented for all remote access, privileged accounts, and critical systems?','guidance'=>'Verify MFA is enabled for VPN, cloud services, email, privileged accounts, and administrative consoles. Check MFA enrollment rates and enforcement policies.','maturity_1'=>'MFA is not implemented or only used for a few systems.','maturity_2'=>'MFA is deployed for some critical systems but not comprehensively enforced.','maturity_3'=>'MFA is required for all remote access, privileged accounts, cloud services, and critical applications with high enrollment rates.','maturity_4'=>'Phishing-resistant MFA (FIDO2/WebAuthn) deployed universally with adaptive authentication and risk-based step-up.','control_examples'=>'Examples: MFA policy, MFA enrollment rate report, Conditional access policy screenshots, FIDO2 key deployment records.','sort_order'=>3],
    ['ref'=>'IAM-04','question'=>'Is privileged access managed through dedicated tools with session monitoring, just-in-time access, and credential vaulting?','guidance'=>'Look for a PAM solution that vaults privileged credentials, provides session recording, enforces just-in-time access, and rotates passwords automatically.','maturity_1'=>'Privileged accounts use shared passwords with no monitoring or vaulting.','maturity_2'=>'Some privileged accounts are managed but without session recording or automated rotation.','maturity_3'=>'PAM solution deployed with credential vaulting, session recording, just-in-time access, and automated password rotation.','maturity_4'=>'Zero standing privileges with fully automated PAM, behavioral analytics, and real-time risk scoring of privileged sessions.','control_examples'=>'Examples: PAM tool deployment evidence, Session recording samples, Password rotation logs, Just-in-time access request records.','sort_order'=>4],
    ['ref'=>'IAM-05','question'=>'Are user access reviews conducted periodically to validate that access rights remain appropriate?','guidance'=>'Verify access reviews are performed at least quarterly for privileged accounts and semi-annually for standard users. Check for reviewer sign-offs and remediation of findings.','maturity_1'=>'No access reviews are performed.','maturity_2'=>'Access reviews happen annually but are inconsistent and findings are not always remediated.','maturity_3'=>'Quarterly access reviews for privileged accounts, semi-annual for all users, with documented sign-offs and tracked remediation.','maturity_4'=>'Continuous access certification with automated anomaly detection, risk-based review frequency, and machine learning recommendations.','control_examples'=>'Examples: Access review schedule, Reviewer sign-off records, Remediation tracking log, Access certification campaign report.','sort_order'=>5],
    ['ref'=>'IAM-06','question'=>'Does the organization enforce strong password policies and secure credential management practices?','guidance'=>'Check password policy settings (length, complexity, history, lockout). Verify credentials are not stored in plain text and a password manager is available for employees.','maturity_1'=>'Weak or no password policy; credentials may be stored insecurely.','maturity_2'=>'Basic password policy exists but may not meet current standards; no enterprise password manager.','maturity_3'=>'Strong password policy enforced (14+ chars, complexity, history), enterprise password manager deployed, no plain-text credential storage.','maturity_4'=>'Passwordless authentication adopted where possible, credential breach monitoring, and adaptive password policies based on risk.','control_examples'=>'Examples: Password policy document, Active Directory policy screenshots, Password manager deployment records, Credential breach monitoring alerts.','sort_order'=>6],
    ['ref'=>'IAM-07','question'=>'Is single sign-on (SSO) implemented to centralize authentication across business applications?','guidance'=>'Look for SSO integration with major business applications using SAML, OIDC, or similar protocols. Check the percentage of applications federated through the identity provider.','maturity_1'=>'No SSO; users maintain separate credentials for each application.','maturity_2'=>'SSO is partially deployed for some cloud applications but not comprehensive.','maturity_3'=>'SSO deployed for majority of applications with SAML/OIDC federation, centralized authentication policies.','maturity_4'=>'Universal SSO with all applications federated, legacy app integration, and centralized session management.','control_examples'=>'Examples: SSO-integrated application list, Identity provider configuration screenshots, SAML federation records, SSO coverage percentage report.','sort_order'=>7],
    ['ref'=>'IAM-08','question'=>'Are service accounts, system accounts, and non-human identities inventoried, secured, and regularly reviewed?','guidance'=>'Verify an inventory of all service accounts exists with assigned owners. Check that service account passwords are rotated, have restricted permissions, and interactive login is disabled where possible.','maturity_1'=>'Service accounts are untracked, use shared passwords, and have excessive privileges.','maturity_2'=>'Some service accounts are documented but reviews and password rotation are inconsistent.','maturity_3'=>'Complete service account inventory with assigned owners, regular password rotation, restricted permissions, and periodic reviews.','maturity_4'=>'Managed service identities with automated credential rotation, certificate-based authentication, and continuous monitoring.','control_examples'=>'Examples: Service account inventory spreadsheet, Password rotation schedules, Owner assignment records, Interactive login restriction evidence.','sort_order'=>8],
    ['ref'=>'IAM-09','question'=>'Are remote access connections secured with encryption, MFA, and monitored for unauthorized use?','guidance'=>'Check VPN, ZTNA, or remote desktop configurations for encryption standards, MFA enforcement, and logging. Verify split-tunnel policies and geo-restriction rules.','maturity_1'=>'Remote access is unrestricted with no encryption or monitoring.','maturity_2'=>'VPN is deployed with basic encryption but MFA may not be enforced for all remote users.','maturity_3'=>'All remote access requires MFA, uses strong encryption, with logging and monitoring for anomalous connections.','maturity_4'=>'Zero trust network access (ZTNA) deployed with continuous device posture assessment and adaptive access policies.','control_examples'=>'Examples: VPN/ZTNA configuration screenshots, MFA enforcement policy, Remote access logs, Geo-restriction rules documentation.','sort_order'=>9],
    ['ref'=>'IAM-10','question'=>'Is a centralized directory service or identity provider used to manage all user identities?','guidance'=>'Look for Active Directory, Azure AD/Entra ID, or equivalent identity provider managing all user accounts. Verify centralized group policies, authentication, and directory synchronization.','maturity_1'=>'No centralized directory; local accounts on individual systems.','maturity_2'=>'Directory service exists but not all systems are integrated; some local accounts persist.','maturity_3'=>'Centralized directory manages all user identities with group policies, synchronized across cloud and on-premises environments.','maturity_4'=>'Unified identity platform with cloud-native directory, real-time sync, and identity analytics for all environments.','control_examples'=>'Examples: Directory service architecture diagram, Group policy configuration, Cloud sync status reports, Account integration coverage report.','sort_order'=>10],
    ['ref'=>'IAM-11','question'=>'Is role-based access control (RBAC) implemented with documented roles mapped to job functions?','guidance'=>'Verify defined roles exist for each job function with documented access permissions. Check that role assignments are based on position, not individual requests.','maturity_1'=>'No defined roles; access is granted individually without standardization.','maturity_2'=>'Some roles are defined for critical systems but not consistently applied across all platforms.','maturity_3'=>'Comprehensive RBAC with documented roles for all job functions, enforced across all systems, and reviewed periodically.','maturity_4'=>'Dynamic RBAC with attribute-based policies, automated role mining, and real-time role optimization based on usage patterns.','control_examples'=>'Examples: Role definition matrix, Role-to-permission mapping document, System role assignment screenshots, Role review records.','sort_order'=>11],
    ['ref'=>'IAM-12','question'=>'Are session management controls implemented including automatic timeouts and re-authentication requirements?','guidance'=>'Check session timeout settings for web applications, VPN, and administrative consoles. Verify inactive sessions are terminated and re-authentication is required for sensitive operations.','maturity_1'=>'No session timeout controls; sessions remain active indefinitely.','maturity_2'=>'Basic timeouts exist for some systems but are inconsistently configured.','maturity_3'=>'Consistent session timeouts across all systems (15-30 min inactivity), re-authentication for sensitive operations, concurrent session limits.','maturity_4'=>'Adaptive session management based on risk context, continuous authentication signals, and automated session anomaly detection.','control_examples'=>'Examples: Session timeout configuration screenshots, Application session policy settings, Re-authentication prompt evidence, Concurrent session limit configuration.','sort_order'=>12],
    ['ref'=>'IAM-13','question'=>'Are emergency or break-glass access procedures documented and monitored for privileged access during emergencies?','guidance'=>'Look for documented procedures for emergency access when normal authentication fails. Verify break-glass accounts are monitored, usage is logged and reviewed, and credentials are changed after use.','maturity_1'=>'No emergency access procedures; staff share admin passwords or bypass security.','maturity_2'=>'Informal emergency access exists but is not documented or monitored.','maturity_3'=>'Documented break-glass procedures with sealed credentials, mandatory usage logging, post-use review, and immediate credential rotation.','maturity_4'=>'Automated break-glass workflow with real-time alerts, automatic credential rotation after use, and integrated incident tracking.','control_examples'=>'Examples: Break-glass procedure document, Sealed credential envelope tracking log, Emergency access usage reports, Post-use review records.','sort_order'=>13],
    ['ref'=>'IAM-14','question'=>'Is authentication for APIs and automated services secured using tokens, certificates, or OAuth rather than embedded credentials?','guidance'=>'Verify API authentication uses secure methods (OAuth 2.0, API keys with rotation, mutual TLS). Check that no credentials are hardcoded in source code or configuration files.','maturity_1'=>'API authentication uses hardcoded credentials or no authentication at all.','maturity_2'=>'API keys are used but not rotated regularly; some embedded credentials may exist.','maturity_3'=>'OAuth 2.0 or certificate-based API authentication with regular key rotation, secrets management, and no hardcoded credentials.','maturity_4'=>'Automated API credential lifecycle with secrets management vault, short-lived tokens, mutual TLS, and continuous scanning for credential leaks.','control_examples'=>'Examples: API authentication configuration, Secrets management vault deployment, Code scanning results for hardcoded credentials, API key rotation logs.','sort_order'=>14],
],

