'DSP' => [
    ['ref'=>'DSP-01','question'=>'Has the organization implemented a data classification scheme that categorizes data by sensitivity level?','guidance'=>'Look for a documented classification scheme (e.g., Public, Internal, Confidential, Restricted) with criteria, handling rules, and labeling requirements for each level.','maturity_1'=>'No data classification scheme exists; all data treated the same.','maturity_2'=>'Classification scheme is defined but not consistently applied across the organization.','maturity_3'=>'Classification scheme with clear criteria and handling rules is implemented, labels applied to data stores, and staff trained.','maturity_4'=>'Automated data discovery and classification with ML-based labeling, real-time policy enforcement, and continuous data inventory.','control_examples'=>'Examples: Data classification policy, Classification labels on documents/systems, Data inventory by classification level, Training completion records.','sort_order'=>1],
    ['ref'=>'DSP-02','question'=>'Is sensitive data encrypted at rest using industry-standard encryption algorithms across all storage locations?','guidance'=>'Verify encryption at rest for databases, file servers, cloud storage, backups, and endpoints. Check encryption algorithms (AES-256 minimum) and key management practices.','maturity_1'=>'No encryption at rest; sensitive data stored in plaintext.','maturity_2'=>'Some systems have encryption but coverage is incomplete; older algorithms may be used.','maturity_3'=>'AES-256 encryption at rest across all storage locations with centralized key management and documented coverage.','maturity_4'=>'Encryption with automated key rotation, hardware-backed key storage (HSM), and continuous compliance monitoring for encryption gaps.','control_examples'=>'Examples: Encryption configuration screenshots, Key management procedure, Encryption coverage report by system, HSM deployment evidence.','sort_order'=>2],
    ['ref'=>'DSP-03','question'=>'Is data encrypted in transit using TLS 1.2 or higher for all internal and external communications?','guidance'=>'Check TLS configurations for web servers, APIs, email, and internal network traffic. Verify certificates are valid and TLS 1.0/1.1 is disabled.','maturity_1'=>'Data transmitted without encryption or using deprecated protocols.','maturity_2'=>'TLS is used for external-facing services but internal traffic may be unencrypted.','maturity_3'=>'TLS 1.2+ enforced for all external and internal communications with certificate management and deprecated protocols disabled.','maturity_4'=>'TLS 1.3 preferred, mutual TLS for service-to-service communication, automated certificate lifecycle, and continuous cipher suite monitoring.','control_examples'=>'Examples: TLS configuration scan results, SSL certificate inventory, Deprecated protocol disable evidence, Internal traffic encryption policy.','sort_order'=>3],
    ['ref'=>'DSP-04','question'=>'Is a data loss prevention (DLP) solution deployed to monitor, detect, and prevent unauthorized data exfiltration?','guidance'=>'Look for DLP controls covering email, web uploads, USB transfers, cloud storage, and endpoint activity. Check DLP policies aligned with data classification.','maturity_1'=>'No DLP controls exist.','maturity_2'=>'Basic email DLP exists but does not cover all exfiltration channels.','maturity_3'=>'Comprehensive DLP across email, web, endpoints, and cloud with policies aligned to data classification and incident review.','maturity_4'=>'AI-driven DLP with user behavior analytics, automated response, and integration with SIEM for correlated analysis.','control_examples'=>'Examples: DLP policy configuration, DLP incident reports, Channel coverage documentation, DLP alert review records.','sort_order'=>4],
    ['ref'=>'DSP-05','question'=>'Are privacy impact assessments (PIAs) conducted for new systems, processes, or projects that handle personal data?','guidance'=>'Verify PIAs are performed before launching new systems or processes involving personal data. Check for PIA templates, completed assessments, and remediation tracking.','maturity_1'=>'No privacy impact assessments are conducted.','maturity_2'=>'PIAs are done for some projects but not systematically required.','maturity_3'=>'PIAs are mandatory for all projects involving personal data, with standard templates, documented findings, and remediation tracking.','maturity_4'=>'Automated PIA workflows integrated into project management, continuous privacy monitoring, and dynamic data mapping.','control_examples'=>'Examples: PIA policy, Completed PIA documents, PIA findings remediation log, Privacy review gate in project lifecycle.','sort_order'=>5],
    ['ref'=>'DSP-06','question'=>'Are data retention schedules defined and enforced, including secure disposal of data that exceeds retention periods?','guidance'=>'Look for documented retention periods by data type, automated enforcement of retention policies, and secure disposal procedures (cryptographic erasure, physical destruction).','maturity_1'=>'No retention schedules; data is kept indefinitely with no disposal process.','maturity_2'=>'Retention schedules exist for some data types but enforcement is manual and inconsistent.','maturity_3'=>'Comprehensive retention schedules enforced with automated deletion, secure disposal procedures, and certificates of destruction.','maturity_4'=>'Automated data lifecycle management with continuous compliance monitoring and legal hold integration.','control_examples'=>'Examples: Data retention schedule, Automated deletion policy configurations, Certificates of destruction, Disposal audit logs.','sort_order'=>6],
    ['ref'=>'DSP-07','question'=>'Does the organization comply with privacy regulations regarding personal data collection, consent, and individual rights?','guidance'=>'Verify compliance with applicable privacy laws (GDPR, CCPA, HIPAA). Check for consent mechanisms, privacy notices, data subject access request procedures, and breach notification processes.','maturity_1'=>'No awareness of or compliance with privacy regulations.','maturity_2'=>'Basic privacy notices exist but consent management and rights processes are incomplete.','maturity_3'=>'Full privacy compliance program with consent management, DSAR procedures, privacy notices, and documented processing activities.','maturity_4'=>'Automated privacy compliance with consent management platform, real-time DSAR fulfillment, and privacy-by-design integration.','control_examples'=>'Examples: Privacy notice, Consent management records, DSAR procedure and completion logs, Records of processing activities (ROPA).','sort_order'=>7],
    ['ref'=>'DSP-08','question'=>'Is data masking or tokenization used to protect sensitive data in non-production environments and for analytics?','guidance'=>'Check that production data used in development, testing, or analytics environments is masked or tokenized. Verify sensitive fields cannot be reversed.','maturity_1'=>'Production data with real PII/sensitive data used directly in non-production environments.','maturity_2'=>'Some data masking exists but coverage is incomplete across all non-production environments.','maturity_3'=>'Automated data masking/tokenization for all non-production environments with irreversible masking for PII and sensitive data.','maturity_4'=>'Dynamic data masking with role-based visibility, synthetic data generation, and automated detection of unmasked sensitive data.','control_examples'=>'Examples: Data masking policy, Masking tool configuration, Non-production environment data audit, Tokenization implementation records.','sort_order'=>8],
    ['ref'=>'DSP-09','question'=>'Are database security controls implemented including access restrictions, query monitoring, and configuration hardening?','guidance'=>'Verify database access is restricted to authorized accounts, administrative access requires MFA, query monitoring detects anomalies, and databases follow hardening benchmarks (CIS).','maturity_1'=>'Databases have default configurations with unrestricted access.','maturity_2'=>'Basic access controls exist but no query monitoring or hardening benchmarks applied.','maturity_3'=>'Database access restricted by role, CIS benchmarks applied, query monitoring active, and administrative access requires MFA.','maturity_4'=>'Database activity monitoring with ML-based anomaly detection, automated hardening compliance, and real-time alerting.','control_examples'=>'Examples: Database access control matrix, CIS benchmark compliance report, Query monitoring alert samples, Database hardening checklist.','sort_order'=>9],
    ['ref'=>'DSP-10','question'=>'Are data backups regularly tested to verify integrity and successful restoration within defined recovery objectives?','guidance'=>'Check backup schedules, test restoration records, and alignment with RTO/RPO. Verify backup encryption and off-site/cloud storage.','maturity_1'=>'Backups exist but are never tested; restoration capability is unknown.','maturity_2'=>'Backups are tested occasionally but not systematically aligned with RTO/RPO targets.','maturity_3'=>'Regular backup testing (at least quarterly) with documented restoration results, encrypted backups, and off-site storage.','maturity_4'=>'Automated backup validation with continuous integrity checking, immutable backups, and instant recovery testing.','control_examples'=>'Examples: Backup schedule documentation, Restoration test records with timestamps, RTO/RPO alignment report, Off-site backup evidence.','sort_order'=>10],
    ['ref'=>'DSP-11','question'=>'Are controls in place to manage cross-border data transfers in compliance with applicable data protection laws?','guidance'=>'Check for data transfer mechanisms (Standard Contractual Clauses, adequacy decisions, binding corporate rules) for international transfers. Verify data residency requirements are met.','maturity_1'=>'No awareness of cross-border transfer requirements; data flows unrestricted.','maturity_2'=>'Some awareness but transfer mechanisms may be incomplete or not documented.','maturity_3'=>'Documented data transfer mechanisms in place, data residency requirements mapped, and transfer impact assessments completed.','maturity_4'=>'Automated data flow mapping with real-time transfer monitoring, dynamic policy enforcement, and continuous compliance assessment.','control_examples'=>'Examples: Data transfer impact assessment, Standard Contractual Clauses, Data flow map showing cross-border transfers, Data residency documentation.','sort_order'=>11],
    ['ref'=>'DSP-12','question'=>'Is a records management program in place to ensure the integrity, availability, and proper handling of business records?','guidance'=>'Look for records management policies, retention schedules, and evidence of proper handling for legal, regulatory, and business records. Check audit trail capabilities.','maturity_1'=>'No records management program exists.','maturity_2'=>'Basic records retention exists but without formal program or comprehensive coverage.','maturity_3'=>'Formal records management program with retention schedules, access controls, audit trails, and legal hold capabilities.','maturity_4'=>'Automated records lifecycle management with intelligent classification, compliance monitoring, and eDiscovery readiness.','control_examples'=>'Examples: Records management policy, Retention schedule by record type, Audit trail reports, Legal hold procedure documentation.','sort_order'=>12],
],

// =========================================================================
// EPS - Endpoint & Platform Security (10 questions)
// =========================================================================
'EPS' => [
    ['ref'=>'EPS-01','question'=>'Is endpoint detection and response (EDR) or equivalent anti-malware protection deployed on all endpoints?','guidance'=>'Verify EDR/AV coverage across all workstations, laptops, and servers. Check for real-time protection, behavioral analysis, and centralized management console.','maturity_1'=>'No endpoint protection or only basic legacy antivirus on some endpoints.','maturity_2'=>'Antivirus deployed but without EDR capabilities or full coverage.','maturity_3'=>'EDR deployed on all endpoints with real-time protection, behavioral analysis, centralized management, and automated response.','maturity_4'=>'XDR platform with cross-layer correlation, automated threat hunting, and integration with SOAR for orchestrated response.','control_examples'=>'Examples: EDR deployment coverage report, Centralized console dashboard screenshot, Detection and response policy, Malware detection logs.','sort_order'=>1],
    ['ref'=>'EPS-02','question'=>'Are operating systems and platforms hardened according to industry benchmarks such as CIS or DISA STIGs?','guidance'=>'Check for documented hardening standards, CIS benchmark compliance scans, and evidence that unnecessary services, ports, and accounts are disabled.','maturity_1'=>'Systems use default configurations with no hardening applied.','maturity_2'=>'Some hardening is applied but not based on a recognized benchmark; inconsistently enforced.','maturity_3'=>'CIS or DISA STIG benchmarks applied to all systems with regular compliance scanning and documented exceptions.','maturity_4'=>'Automated hardening with infrastructure-as-code, continuous compliance drift detection, and auto-remediation.','control_examples'=>'Examples: CIS benchmark compliance scan report, Hardening standard document, Configuration baseline records, Exception documentation.','sort_order'=>2],
    ['ref'=>'EPS-03','question'=>'Is a patch management program in place to deploy security updates to all endpoints within defined timeframes?','guidance'=>'Verify patch management covers OS, applications, and firmware. Check SLAs for critical patches (e.g., 14 days for critical, 30 days for high). Review patch compliance reports.','maturity_1'=>'No formal patch management; updates are ad hoc or never applied.','maturity_2'=>'Patching occurs but without defined SLAs, full coverage, or compliance tracking.','maturity_3'=>'Formal patch program with defined SLAs, automated deployment, coverage tracking, and exception management.','maturity_4'=>'Risk-based patching with automated prioritization, zero-day response procedures, and near-100% compliance rates.','control_examples'=>'Examples: Patch management policy with SLAs, Patch compliance percentage report, Automated deployment tool dashboard, Exception/deferral records.','sort_order'=>3],
    ['ref'=>'EPS-04','question'=>'Is mobile device management (MDM) deployed to enforce security policies on smartphones and tablets?','guidance'=>'Check MDM enrollment rates, policy enforcement (passcode, encryption, remote wipe), app management, and conditional access tied to device compliance.','maturity_1'=>'No MDM; personal and corporate mobile devices are unmanaged.','maturity_2'=>'MDM exists but enrollment is optional or policies are not comprehensive.','maturity_3'=>'MDM required for all corporate mobile devices with encryption, passcode, remote wipe, and conditional access enforcement.','maturity_4'=>'Unified endpoint management with BYOD containerization, continuous device posture assessment, and automated compliance remediation.','control_examples'=>'Examples: MDM enrollment rate report, Mobile security policy, Remote wipe capability test records, Conditional access policy screenshots.','sort_order'=>4],
    ['ref'=>'EPS-05','question'=>'Are controls in place to restrict or monitor the use of removable media and USB storage devices?','guidance'=>'Verify USB mass storage is blocked or restricted via endpoint policy. Check for exceptions process and monitoring of removable media usage.','maturity_1'=>'No restrictions on USB or removable media usage.','maturity_2'=>'USB restrictions exist for some systems but are not consistently enforced.','maturity_3'=>'USB mass storage blocked across all endpoints via policy with documented exceptions and usage monitoring.','maturity_4'=>'Granular device control with allowlisting specific devices, encrypted-only media enforcement, and automated DLP for removable media.','control_examples'=>'Examples: USB restriction policy configuration screenshots, Group Policy/MDM settings, Exception approval records, Removable media usage logs.','sort_order'=>5],
    ['ref'=>'EPS-06','question'=>'Is a comprehensive hardware and software asset inventory maintained and kept current?','guidance'=>'Look for an automated asset discovery tool that maintains inventory of all hardware and software assets. Check for asset owners, classification, and regular reconciliation.','maturity_1'=>'No asset inventory exists or it is severely outdated.','maturity_2'=>'Partial inventory exists but relies on manual updates and does not cover all assets.','maturity_3'=>'Automated asset discovery with comprehensive inventory of hardware and software, assigned owners, and regular reconciliation.','maturity_4'=>'Real-time asset inventory with automated discovery, classification, lifecycle tracking, and integration with vulnerability management.','control_examples'=>'Examples: Asset inventory database/report, Automated discovery tool dashboard, Asset reconciliation records, Unauthorized asset detection alerts.','sort_order'=>6],
    ['ref'=>'EPS-07','question'=>'Is application whitelisting or allowlisting enforced to prevent unauthorized software execution?','guidance'=>'Check for application control policies that restrict execution to approved applications. Verify the allowlist is maintained and unauthorized execution attempts are logged.','maturity_1'=>'No application control; any software can be installed and executed.','maturity_2'=>'Basic software restrictions exist but are easily bypassed or not comprehensively enforced.','maturity_3'=>'Application allowlisting enforced on all endpoints with maintained approved list, blocked execution logging, and exception process.','maturity_4'=>'Dynamic application trust with automated reputation analysis, publisher-based rules, and integration with threat intelligence.','control_examples'=>'Examples: Application control policy configuration, Approved software list, Blocked execution attempt logs, Exception request records.','sort_order'=>7],
    ['ref'=>'EPS-08','question'=>'Are secure configuration baselines documented and enforced for all endpoint types?','guidance'=>'Verify documented baselines exist for each endpoint type (Windows, macOS, Linux, servers). Check for automated configuration management and drift detection.','maturity_1'=>'No configuration baselines; each system configured independently.','maturity_2'=>'Informal baselines exist but are not consistently enforced or monitored.','maturity_3'=>'Documented baselines for each platform, deployed via configuration management tools, with regular drift detection and remediation.','maturity_4'=>'Infrastructure-as-code baselines with automated deployment, continuous drift detection, and auto-remediation within minutes.','control_examples'=>'Examples: Configuration baseline documents per OS type, Configuration management tool deployment evidence, Drift detection scan results, Remediation records.','sort_order'=>8],
    ['ref'=>'EPS-09','question'=>'Are endpoint data backup policies in place to protect against data loss from ransomware or hardware failure?','guidance'=>'Check that endpoint data is backed up (cloud sync, local backup, or enterprise backup solution). Verify backup encryption and recovery testing for endpoints.','maturity_1'=>'No endpoint backup; data loss from ransomware or failure would be permanent.','maturity_2'=>'Some backup exists (e.g., OneDrive sync) but not comprehensive or enforced across all endpoints.','maturity_3'=>'Enterprise endpoint backup with cloud sync or scheduled backups, encryption, and tested recovery procedures.','maturity_4'=>'Continuous endpoint backup with immutable copies, ransomware-resistant recovery, and automated verification of backup integrity.','control_examples'=>'Examples: Endpoint backup policy, Cloud sync configuration (OneDrive/Dropbox), Backup tool deployment records, Recovery test results.','sort_order'=>9],
    ['ref'=>'EPS-10','question'=>'Are virtual desktop infrastructure (VDI) or cloud workspaces secured with appropriate access controls and data protection?','guidance'=>'If VDI/DaaS is used, verify secure access controls, data does not leave the virtual environment, session recording is available, and images are hardened.','maturity_1'=>'VDI/cloud workspaces not applicable or deployed without security controls.','maturity_2'=>'VDI is deployed but security configurations are basic and data leakage controls are limited.','maturity_3'=>'VDI secured with MFA, clipboard/print restrictions, hardened images, and monitored access.','maturity_4'=>'Zero-trust VDI with continuous device posture validation, watermarked sessions, and automated image lifecycle management.','control_examples'=>'Examples: VDI security configuration, Clipboard/print restriction settings, Image hardening checklist, VDI access logs with MFA verification.','sort_order'=>10],
],

// =========================================================================
// NET - Network Security (11 questions)
// =========================================================================
'NET' => [
    ['ref'=>'NET-01','question'=>'Is the network segmented to isolate sensitive systems, environments, and data from general-purpose networks?','guidance'=>'Verify network segmentation between production/development, PCI CDE, guest networks, and IoT. Check firewall rules between segments and VLAN configurations.','maturity_1'=>'Flat network with no segmentation; all systems on one network.','maturity_2'=>'Basic VLANs exist but segmentation is incomplete and inter-VLAN filtering is minimal.','maturity_3'=>'Network segmented by function and sensitivity with enforced firewall rules between segments and documented architecture.','maturity_4'=>'Microsegmentation with zero-trust policies, dynamic segment assignment based on workload identity, and continuous verification.','control_examples'=>'Examples: Network architecture diagram showing segments, VLAN configuration, Firewall rules between zones, Segmentation test results.','sort_order'=>1],
    ['ref'=>'NET-02','question'=>'Are firewalls deployed at network boundaries with documented rule sets that are regularly reviewed?','guidance'=>'Check firewall placement at internet boundary, between network zones, and for cloud environments. Verify rule reviews occur at least semi-annually with unused rules removed.','maturity_1'=>'No firewalls or default-allow configurations at network boundaries.','maturity_2'=>'Firewalls exist but rules are not documented, reviewed, or optimized.','maturity_3'=>'Next-gen firewalls at all boundaries with documented rules, semi-annual review, unused rule removal, and change management.','maturity_4'=>'Automated rule optimization with continuous traffic analysis, policy-as-code, and real-time threat intelligence integration.','control_examples'=>'Examples: Firewall rule documentation, Rule review meeting minutes, Unused rule cleanup evidence, Change management records for rule changes.','sort_order'=>2],
    ['ref'=>'NET-03','question'=>'Are intrusion detection and prevention systems (IDS/IPS) deployed to monitor network traffic for threats?','guidance'=>'Verify IDS/IPS deployment at key network points with up-to-date signatures. Check for tuning to reduce false positives and integration with SIEM.','maturity_1'=>'No IDS/IPS deployed; network threats go undetected.','maturity_2'=>'IDS is deployed at some points but signatures are outdated and alerts are not actively monitored.','maturity_3'=>'IDS/IPS at all critical points with current signatures, tuned alerts, SIEM integration, and active monitoring.','maturity_4'=>'ML-based network detection with behavioral analysis, automated threat response, and continuous tuning based on threat intelligence.','control_examples'=>'Examples: IDS/IPS deployment diagram, Signature update schedule, Alert tuning records, SIEM correlation rule evidence.','sort_order'=>3],
    ['ref'=>'NET-04','question'=>'Is secure remote access provided through VPN, ZTNA, or equivalent with strong authentication and encryption?','guidance'=>'Verify all remote access uses encrypted tunnels (IPsec, TLS) with MFA. Check for split-tunnel controls, session logging, and geographic restrictions.','maturity_1'=>'Remote access is uncontrolled or uses unencrypted connections.','maturity_2'=>'VPN deployed but may lack MFA enforcement or comprehensive logging.','maturity_3'=>'All remote access through VPN/ZTNA with MFA, strong encryption, session logging, and geographic restrictions.','maturity_4'=>'ZTNA with continuous device posture assessment, adaptive access policies, and per-application micro-tunnels.','control_examples'=>'Examples: VPN/ZTNA architecture diagram, MFA enforcement configuration, Session logs, Geographic restriction policy.','sort_order'=>4],
    ['ref'=>'NET-05','question'=>'Are wireless networks secured with enterprise-grade authentication (WPA3/WPA2-Enterprise) and monitored for rogue access points?','guidance'=>'Check wireless authentication standards, guest network isolation, and rogue AP detection. Verify wireless traffic is encrypted and monitored.','maturity_1'=>'Wireless uses PSK or open networks with no monitoring.','maturity_2'=>'WPA2-Personal used with shared keys; limited rogue AP detection.','maturity_3'=>'WPA3 or WPA2-Enterprise with 802.1X authentication, guest isolation, rogue AP detection, and wireless IDS.','maturity_4'=>'Cloud-managed wireless with automated rogue AP containment, RF analytics, and integration with NAC.','control_examples'=>'Examples: Wireless authentication configuration, Guest network isolation evidence, Rogue AP detection scan results, 802.1X certificate deployment records.','sort_order'=>5],
    ['ref'=>'NET-06','question'=>'Are DNS security controls implemented to prevent DNS-based attacks and block malicious domains?','guidance'=>'Check for DNS filtering, DNSSEC validation, DNS logging, and protection against DNS tunneling and typosquatting.','maturity_1'=>'No DNS security controls; default ISP DNS used.','maturity_2'=>'Basic DNS filtering exists but limited coverage and no advanced threat detection.','maturity_3'=>'DNS security service with malicious domain blocking, DNSSEC validation, DNS logging, and tunneling detection.','maturity_4'=>'Advanced DNS analytics with real-time threat intelligence, DGA detection, and automated response to DNS-based threats.','control_examples'=>'Examples: DNS security service configuration, Blocked domain reports, DNS query logs, DNSSEC validation evidence.','sort_order'=>6],
    ['ref'=>'NET-07','question'=>'Is network traffic continuously monitored with tools to detect anomalous behavior and potential security incidents?','guidance'=>'Look for network monitoring tools (NetFlow, packet capture, NDR) with baseline traffic patterns and anomaly detection capabilities.','maturity_1'=>'No network traffic monitoring beyond basic availability checks.','maturity_2'=>'Basic monitoring exists but without behavioral analysis or anomaly detection.','maturity_3'=>'Continuous network monitoring with traffic analysis, baseline profiling, anomaly detection, and alerting to SOC.','maturity_4'=>'AI-driven network detection and response (NDR) with behavioral analytics, automated investigation, and threat hunting.','control_examples'=>'Examples: Network monitoring tool dashboard, Anomaly detection alert samples, Traffic baseline documentation, NDR deployment evidence.','sort_order'=>7],
    ['ref'=>'NET-08','question'=>'Are DDoS mitigation controls in place to protect internet-facing services from volumetric and application-layer attacks?','guidance'=>'Verify DDoS protection for critical internet-facing services. Check for CDN-based protection, scrubbing centers, or ISP-level mitigation.','maturity_1'=>'No DDoS protection; services vulnerable to volumetric attacks.','maturity_2'=>'Basic ISP-level DDoS protection but no application-layer defense.','maturity_3'=>'Multi-layer DDoS protection covering volumetric and application-layer attacks with automated mitigation and documented runbooks.','maturity_4'=>'Adaptive DDoS protection with real-time traffic profiling, automated scaling, and integrated with incident response.','control_examples'=>'Examples: DDoS protection service configuration, Mitigation test results, Runbook documentation, Historical attack mitigation reports.','sort_order'=>8],
    ['ref'=>'NET-09','question'=>'Is network access control (NAC) implemented to authenticate devices before granting network access?','guidance'=>'Check for NAC solution that validates device identity, health, and compliance before allowing network access. Verify remediation VLAN for non-compliant devices.','maturity_1'=>'No NAC; any device can connect to the network.','maturity_2'=>'Basic port security exists but no comprehensive NAC with health checks.','maturity_3'=>'NAC with 802.1X authentication, device health checks, compliance validation, and remediation VLAN for non-compliant devices.','maturity_4'=>'Adaptive NAC with real-time posture assessment, automated micro-segmentation, and continuous device trust scoring.','control_examples'=>'Examples: NAC policy configuration, 802.1X deployment evidence, Device health check results, Remediation VLAN configuration.','sort_order'=>9],
    ['ref'=>'NET-10','question'=>'Is the network architecture documented with up-to-date diagrams showing all segments, trust zones, and data flows?','guidance'=>'Look for current network diagrams showing physical and logical topology, security zones, data flow paths, and external connections. Verify diagrams are reviewed annually.','maturity_1'=>'No network documentation or diagrams exist.','maturity_2'=>'Outdated network diagrams exist but do not reflect current architecture.','maturity_3'=>'Current network diagrams maintained with all segments, trust zones, data flows, and external connections. Reviewed annually.','maturity_4'=>'Automated network topology mapping with real-time updates, data flow visualization, and integration with asset inventory.','control_examples'=>'Examples: Network architecture diagram, Data flow diagram, Trust zone documentation, Annual review records, External connection inventory.','sort_order'=>10],
    ['ref'=>'NET-11','question'=>'Are cloud network security controls (VPCs, security groups, NACLs) configured and monitored for cloud environments?','guidance'=>'Verify cloud network architecture uses VPCs with appropriate subnets, security groups with least-privilege rules, and NACLs. Check for cloud network flow logging.','maturity_1'=>'Cloud network uses default configurations with no security group management.','maturity_2'=>'Basic security groups exist but rules are overly permissive and not regularly reviewed.','maturity_3'=>'VPCs with segmented subnets, least-privilege security groups, NACLs, flow logging, and regular review of cloud network rules.','maturity_4'=>'Infrastructure-as-code cloud networking with automated compliance checks, drift detection, and policy-as-code for security groups.','control_examples'=>'Examples: VPC architecture diagram, Security group rules documentation, Flow log analysis, Cloud network compliance scan results.','sort_order'=>11],
],

// =========================================================================
// APS - Application Security (10 questions)
// =========================================================================
'APS' => [
    ['ref'=>'APS-01','question'=>'Is a secure software development lifecycle (SSDLC) implemented with security activities integrated at each phase?','guidance'=>'Verify security is integrated into requirements, design, development, testing, and deployment phases. Look for threat modeling, secure coding standards, and security testing.','maturity_1'=>'No security in the SDLC; security testing happens only in production, if at all.','maturity_2'=>'Some security activities exist (e.g., penetration testing before release) but not integrated across all phases.','maturity_3'=>'SSDLC with threat modeling, secure coding standards, SAST/DAST, security review gates, and developer security training.','maturity_4'=>'DevSecOps with automated security in CI/CD pipeline, shift-left security, and continuous security feedback loops.','control_examples'=>'Examples: SSDLC process document, Threat model examples, Security gate checklist, CI/CD security scan integration evidence.','sort_order'=>1],
    ['ref'=>'APS-02','question'=>'Is static application security testing (SAST) or code review performed on source code before deployment?','guidance'=>'Check for SAST tools integrated into CI/CD pipeline or manual code review processes. Verify critical/high findings must be remediated before deployment.','maturity_1'=>'No code review or security analysis of source code.','maturity_2'=>'Manual code reviews occur but no automated SAST scanning.','maturity_3'=>'SAST integrated into CI/CD with automated scanning, required remediation of critical/high findings, and developer feedback.','maturity_4'=>'Real-time SAST with IDE integration, AI-assisted remediation suggestions, and continuous code quality scoring.','control_examples'=>'Examples: SAST tool scan results, CI/CD pipeline security stage configuration, Code review records, Remediation tracking for findings.','sort_order'=>2],
    ['ref'=>'APS-03','question'=>'Is dynamic application security testing (DAST) performed on running applications to identify runtime vulnerabilities?','guidance'=>'Verify DAST scanning of web applications and APIs before release and on a regular schedule. Check for OWASP Top 10 coverage and remediation tracking.','maturity_1'=>'No dynamic testing of applications.','maturity_2'=>'DAST scans run occasionally but not consistently or without remediation tracking.','maturity_3'=>'DAST integrated into release process with OWASP Top 10 coverage, regular scans, and tracked remediation of findings.','maturity_4'=>'Continuous DAST with IAST integration, automated crawling, and real-time vulnerability detection in staging environments.','control_examples'=>'Examples: DAST scan reports, OWASP Top 10 coverage evidence, Vulnerability remediation records, Scan schedule documentation.','sort_order'=>3],
    ['ref'=>'APS-04','question'=>'Is a web application firewall (WAF) deployed to protect internet-facing applications from common web attacks?','guidance'=>'Verify WAF coverage for all internet-facing web applications and APIs. Check for OWASP Top 10 rule sets, custom rules, and regular rule updates.','maturity_1'=>'No WAF protection for web applications.','maturity_2'=>'WAF deployed for some applications but with basic or default rules.','maturity_3'=>'WAF protecting all internet-facing applications with OWASP rule sets, custom rules, regular tuning, and blocking mode.','maturity_4'=>'Adaptive WAF with ML-based threat detection, bot management, API-specific protection, and automated rule generation.','control_examples'=>'Examples: WAF deployment architecture, Rule set configuration, WAF alert and block logs, Custom rule documentation.','sort_order'=>4],
    ['ref'=>'APS-05','question'=>'Are API security controls implemented including authentication, rate limiting, input validation, and monitoring?','guidance'=>'Check API authentication mechanisms (OAuth 2.0, API keys), rate limiting configurations, input validation, and API activity logging.','maturity_1'=>'APIs lack authentication or use basic mechanisms with no rate limiting.','maturity_2'=>'APIs have authentication but may lack rate limiting, input validation, or comprehensive monitoring.','maturity_3'=>'All APIs secured with OAuth 2.0 or equivalent, rate limiting, input validation, schema validation, and activity logging.','maturity_4'=>'API security gateway with behavioral analysis, automated threat detection, API discovery, and runtime protection.','control_examples'=>'Examples: API authentication configuration, Rate limiting settings, Input validation rules, API activity monitoring dashboard.','sort_order'=>5],
    ['ref'=>'APS-06','question'=>'Is open source and third-party library management in place with vulnerability scanning and license compliance?','guidance'=>'Look for software composition analysis (SCA) tools that scan dependencies for known vulnerabilities. Check for vulnerability remediation SLAs and license tracking.','maturity_1'=>'No tracking of open source dependencies or known vulnerabilities.','maturity_2'=>'Some awareness of dependencies but no automated scanning or remediation process.','maturity_3'=>'SCA integrated into CI/CD with automated vulnerability scanning, remediation SLAs, and license compliance tracking.','maturity_4'=>'Real-time dependency monitoring with automated pull requests for updates, SBOM generation, and supply chain security verification.','control_examples'=>'Examples: SCA scan results, Dependency inventory (SBOM), Vulnerability remediation records, License compliance report.','sort_order'=>6],
    ['ref'=>'APS-07','question'=>'Is a formal change management process in place for all production system changes with approval and rollback procedures?','guidance'=>'Verify changes to production require documented requests, risk assessment, approval, testing, and rollback plans. Check change advisory board (CAB) processes.','maturity_1'=>'No change management; production changes made directly without approval.','maturity_2'=>'Informal change process exists but approvals and documentation are inconsistent.','maturity_3'=>'Formal change management with documented requests, risk assessment, CAB approval, testing requirements, and rollback procedures.','maturity_4'=>'Automated change management integrated with CI/CD, automated testing gates, and risk-based approval workflows.','control_examples'=>'Examples: Change management policy, Change request forms/tickets, CAB meeting minutes, Rollback procedure documentation.','sort_order'=>7],
    ['ref'=>'APS-08','question'=>'Are release management and deployment controls in place to ensure secure and reliable software releases?','guidance'=>'Check for deployment pipelines, environment promotion gates, deployment approval processes, and separation of development/staging/production.','maturity_1'=>'No formal release process; code deployed directly to production.','maturity_2'=>'Basic release process exists but environment separation or approval gates are incomplete.','maturity_3'=>'Formal release process with environment separation, approval gates, automated deployment pipelines, and deployment verification.','maturity_4'=>'Fully automated CI/CD with canary/blue-green deployments, automated rollback, and deployment security verification.','control_examples'=>'Examples: Deployment pipeline configuration, Environment promotion evidence, Release approval records, Deployment verification checklists.','sort_order'=>8],
    ['ref'=>'APS-09','question'=>'Are secure coding standards documented and enforced through training and automated tooling?','guidance'=>'Look for documented coding standards that address OWASP Top 10, input validation, output encoding, and language-specific best practices. Check developer training records.','maturity_1'=>'No secure coding standards; developers follow no security guidance.','maturity_2'=>'General coding standards exist but security-specific guidance is limited or not enforced.','maturity_3'=>'Secure coding standards documented for each language, developer security training provided, and enforcement via linting and code review.','maturity_4'=>'AI-assisted secure coding with real-time IDE suggestions, gamified developer training, and continuous coding standard evolution.','control_examples'=>'Examples: Secure coding standards document, Developer security training completion records, Linting configuration, Code review checklist.','sort_order'=>9],
    ['ref'=>'APS-10','question'=>'Is application vulnerability scanning performed regularly on production applications with tracked remediation?','guidance'=>'Verify regular vulnerability scanning of all production applications (web, mobile, API). Check scan frequency, coverage, and remediation SLAs.','maturity_1'=>'No application vulnerability scanning.','maturity_2'=>'Occasional scanning of some applications without consistent remediation.','maturity_3'=>'Regular scanning of all production applications with defined SLAs, tracked remediation, and risk acceptance for exceptions.','maturity_4'=>'Continuous scanning with automated remediation workflows, trend analysis, and integration with development backlog.','control_examples'=>'Examples: Vulnerability scan reports, Remediation tracking dashboard, Scan coverage report, Risk acceptance documentation for exceptions.','sort_order'=>10],
],

// =========================================================================
// OPS - Security Operations (12 questions)
// =========================================================================
'OPS' => [
    ['ref'=>'OPS-01','question'=>'Is a SIEM or equivalent log correlation platform deployed for centralized security monitoring and alerting?','guidance'=>'Verify SIEM collects logs from all critical systems, has correlation rules for known attack patterns, and generates actionable alerts monitored 24/7 or during business hours.','maturity_1'=>'No centralized logging or SIEM; logs are siloed across systems.','maturity_2'=>'Basic log aggregation exists but limited correlation rules and monitoring.','maturity_3'=>'SIEM deployed with logs from all critical systems, tuned correlation rules, defined alert escalation, and SOC monitoring.','maturity_4'=>'Advanced SIEM with UEBA, automated investigation playbooks, threat hunting, and ML-driven anomaly detection.','control_examples'=>'Examples: SIEM architecture diagram, Log source inventory, Correlation rule list, Alert escalation procedures, SOC operations schedule.','sort_order'=>1],
    ['ref'=>'OPS-02','question'=>'Does the organization have a security operations center (SOC) or equivalent monitoring capability for real-time threat detection?','guidance'=>'Check for 24/7 or business-hours SOC (internal or MSSP/MDR) with defined procedures, escalation paths, and response capabilities.','maturity_1'=>'No dedicated monitoring; security events go unnoticed until impact.','maturity_2'=>'Part-time monitoring exists but without dedicated staff or consistent coverage.','maturity_3'=>'SOC or MDR service provides continuous monitoring with defined procedures, escalation paths, and regular reporting.','maturity_4'=>'Hybrid SOC with threat hunting, automated triage, and proactive threat intelligence integration.','control_examples'=>'Examples: SOC operational procedures, Monitoring coverage schedule, MSSP/MDR contract and SLAs, Monthly SOC performance report.','sort_order'=>2],
    ['ref'=>'OPS-03','question'=>'Are security logs retained for a sufficient period and protected from tampering or unauthorized access?','guidance'=>'Verify log retention meets regulatory requirements (typically 1-7 years). Check that logs are stored immutably, access-controlled, and integrity is verified.','maturity_1'=>'Logs are not retained or are kept for very short periods with no protection.','maturity_2'=>'Logs retained for some period but without integrity protection or access controls.','maturity_3'=>'Logs retained per regulatory requirements (min 1 year) with integrity controls, access restrictions, and tamper evidence.','maturity_4'=>'Immutable log storage with cryptographic integrity verification, automated retention management, and forensic readiness.','control_examples'=>'Examples: Log retention policy, Log storage configuration, Access control evidence for log systems, Integrity verification records.','sort_order'=>3],
    ['ref'=>'OPS-04','question'=>'Is a vulnerability management program in place with regular scanning, risk-based prioritization, and defined remediation SLAs?','guidance'=>'Verify vulnerability scanning covers all assets (internal, external, cloud). Check for risk-based prioritization (CVSS, EPSS), remediation SLAs, and exception management.','maturity_1'=>'No vulnerability scanning or management program.','maturity_2'=>'Occasional scans performed but no consistent prioritization or remediation tracking.','maturity_3'=>'Regular scanning of all assets with risk-based prioritization, defined SLAs (critical: 7 days, high: 30 days), and tracked remediation.','maturity_4'=>'Continuous vulnerability assessment with CTEM, automated prioritization using EPSS, and integration with patch management.','control_examples'=>'Examples: Vulnerability management policy, Scan results dashboard, Remediation SLA tracking report, Exception/risk acceptance records.','sort_order'=>4],
    ['ref'=>'OPS-05','question'=>'Is a patch management program implemented for all infrastructure including servers, network devices, and applications?','guidance'=>'Beyond endpoint patching (covered in EPS-03), verify patching of servers, network equipment, firmware, databases, and middleware with defined SLAs and compliance tracking.','maturity_1'=>'No infrastructure patch management; systems remain unpatched.','maturity_2'=>'Some patching occurs but without SLAs, full coverage, or compliance tracking for infrastructure.','maturity_3'=>'Comprehensive patch program covering all infrastructure with defined SLAs, automation, testing, and compliance tracking.','maturity_4'=>'Automated risk-based patching with zero-day response, virtual patching capabilities, and near-100% compliance.','control_examples'=>'Examples: Infrastructure patch policy, Server/network patch compliance reports, Patching automation tool evidence, Patch testing records.','sort_order'=>5],
    ['ref'=>'OPS-06','question'=>'Does the organization leverage threat intelligence to inform security operations and proactive defense?','guidance'=>'Check for threat intelligence feeds integrated into SIEM/IPS, membership in information sharing groups (ISACs), and use of threat intelligence in decision-making.','maturity_1'=>'No threat intelligence capability or awareness.','maturity_2'=>'Some open-source threat feeds used but not systematically integrated.','maturity_3'=>'Multiple threat intelligence sources integrated into SIEM/IPS, ISAC membership, and regular threat briefings to security team.','maturity_4'=>'Curated threat intelligence with automated indicator enrichment, proactive threat hunting, and tailored intelligence reports.','control_examples'=>'Examples: Threat intelligence feed subscriptions, ISAC membership evidence, Threat briefing records, SIEM indicator integration.','sort_order'=>6],
    ['ref'=>'OPS-07','question'=>'Are security tools and technologies inventoried, managed, and regularly evaluated for effectiveness?','guidance'=>'Verify an inventory of all security tools exists with owners, licensing, health monitoring, and periodic effectiveness reviews.','maturity_1'=>'No security tool inventory; tools are deployed ad hoc without oversight.','maturity_2'=>'Some tools are tracked but without health monitoring or effectiveness evaluation.','maturity_3'=>'Complete security tool inventory with assigned owners, health monitoring, license tracking, and annual effectiveness reviews.','maturity_4'=>'Security tool rationalization with overlap analysis, automated health dashboards, and continuous ROI measurement.','control_examples'=>'Examples: Security tool inventory, License tracking spreadsheet, Tool health monitoring dashboard, Effectiveness review reports.','sort_order'=>7],
    ['ref'=>'OPS-08','question'=>'Is a configuration management database (CMDB) or process maintained to track and control system configurations?','guidance'=>'Check for configuration management practices that maintain authorized configurations, detect unauthorized changes, and support change management.','maturity_1'=>'No configuration management; system configurations are unknown or uncontrolled.','maturity_2'=>'Some configuration documentation exists but is not consistently maintained.','maturity_3'=>'Configuration management with maintained CMDB, authorized baselines, change detection, and regular audits.','maturity_4'=>'Automated configuration management with infrastructure-as-code, continuous compliance, and auto-remediation of drift.','control_examples'=>'Examples: CMDB or configuration inventory, Authorized baseline documents, Change detection alerts, Configuration audit reports.','sort_order'=>8],
    ['ref'=>'OPS-09','question'=>'Is capacity management performed to ensure security infrastructure can handle current and projected workloads?','guidance'=>'Verify monitoring of security system capacity (SIEM storage, firewall throughput, log capacity). Check for capacity planning aligned with business growth.','maturity_1'=>'No capacity planning for security infrastructure.','maturity_2'=>'Basic monitoring exists but no proactive planning or trend analysis.','maturity_3'=>'Capacity monitoring for all security infrastructure with trend analysis, threshold alerts, and annual capacity planning.','maturity_4'=>'Predictive capacity management with auto-scaling, cloud-bursting capabilities, and ML-based forecasting.','control_examples'=>'Examples: Capacity monitoring dashboards, Storage utilization trends, Capacity planning documents, Auto-scaling configuration.','sort_order'=>9],
    ['ref'=>'OPS-10','question'=>'Are all systems synchronized to authoritative time sources to ensure accurate log correlation and forensic analysis?','guidance'=>'Verify NTP configuration on all systems pointing to authoritative time sources. Check for consistent timezone handling and time synchronization monitoring.','maturity_1'=>'No time synchronization; system clocks vary across infrastructure.','maturity_2'=>'Some systems use NTP but configuration is inconsistent.','maturity_3'=>'All systems synchronized to authoritative NTP sources with consistent timezone handling and synchronization monitoring.','maturity_4'=>'GPS-synchronized time sources with sub-millisecond accuracy, automated drift alerts, and forensic-grade timestamps.','control_examples'=>'Examples: NTP configuration evidence, Time synchronization monitoring dashboard, Clock variance report, NTP server architecture.','sort_order'=>10],
    ['ref'=>'OPS-11','question'=>'Is a penetration testing program in place with regular testing of applications, infrastructure, and cloud environments?','guidance'=>'Verify penetration testing scope, frequency (at least annual), and remediation tracking. Check for qualified testers (internal or third-party) and re-testing of findings.','maturity_1'=>'No penetration testing performed.','maturity_2'=>'Penetration testing is done occasionally but without consistent scope or remediation follow-up.','maturity_3'=>'Annual penetration testing of applications, infrastructure, and cloud by qualified testers with tracked remediation and re-testing.','maturity_4'=>'Continuous penetration testing with red team/purple team exercises, automated breach simulation, and offensive security program.','control_examples'=>'Examples: Penetration test reports, Tester qualifications/certifications, Remediation tracking records, Re-test verification results.','sort_order'=>11],
    ['ref'=>'OPS-12','question'=>'Does the organization conduct red team, blue team, or purple team exercises to validate defensive capabilities?','guidance'=>'Look for exercises that test detection, response, and recovery capabilities against realistic attack scenarios. Check for exercise reports and improvement actions.','maturity_1'=>'No adversary simulation or team exercises conducted.','maturity_2'=>'Occasional tabletop exercises without technical validation of defenses.','maturity_3'=>'Annual red/purple team exercises with realistic scenarios, documented findings, and tracked improvement actions.','maturity_4'=>'Continuous adversary simulation with automated breach and attack simulation (BAS), real-time detection validation, and adaptive defense improvement.','control_examples'=>'Examples: Red team exercise report, Purple team collaboration records, Detection gap analysis, Improvement action tracking.','sort_order'=>12],
],

// =========================================================================
// INC - Incident Management (10 questions)
// =========================================================================
'INC' => [
    ['ref'=>'INC-01','question'=>'Does the organization have a documented incident response plan that is approved by management and regularly tested?','guidance'=>'Look for a comprehensive IRP covering detection, containment, eradication, recovery, and lessons learned. Verify management approval and regular testing (tabletop/functional).','maturity_1'=>'No incident response plan exists.','maturity_2'=>'Basic IRP exists but has not been tested or is outdated.','maturity_3'=>'Comprehensive IRP approved by management, tested at least annually via tabletop exercises, with documented procedures for all phases.','maturity_4'=>'IRP is continuously updated based on threat intelligence, includes automated playbooks, and is tested through realistic simulations.','control_examples'=>'Examples: Incident response plan document, Management approval signature, Tabletop exercise records, After-action reports.','sort_order'=>1],
    ['ref'=>'INC-02','question'=>'Is an incident classification and severity framework defined to prioritize response activities?','guidance'=>'Check for severity levels (Critical/High/Medium/Low) with clear criteria, response time SLAs, and escalation procedures for each severity.','maturity_1'=>'No incident classification; all incidents treated the same way.','maturity_2'=>'Informal severity levels exist but criteria are not documented or consistently applied.','maturity_3'=>'Defined severity framework with clear criteria, response SLAs, escalation paths, and documented for all incident types.','maturity_4'=>'Dynamic severity assessment with automated classification based on asset criticality, data sensitivity, and threat intelligence.','control_examples'=>'Examples: Incident severity matrix, Response SLA table, Escalation procedures, Classification decision tree.','sort_order'=>2],
    ['ref'=>'INC-03','question'=>'Are automated detection capabilities in place to identify security incidents in real-time or near-real-time?','guidance'=>'Verify detection controls including SIEM alerts, EDR detections, network anomaly detection, and user behavior analytics that enable rapid incident identification.','maturity_1'=>'Incident detection relies on manual observation or user reports.','maturity_2'=>'Some automated detection exists but coverage gaps leave many incident types undetected.','maturity_3'=>'Comprehensive automated detection with SIEM, EDR, network monitoring, and email security covering all major attack vectors.','maturity_4'=>'ML-driven detection with UEBA, automated alert triage, and mean time to detect (MTTD) measured and continuously improving.','control_examples'=>'Examples: SIEM detection rule inventory, EDR alert dashboard, Detection coverage matrix, MTTD metrics report.','sort_order'=>3],
    ['ref'=>'INC-04','question'=>'Are containment procedures defined to rapidly isolate affected systems and prevent incident spread?','guidance'=>'Check for documented containment strategies (network isolation, account disabling, host quarantine) with decision criteria and authorization procedures.','maturity_1'=>'No containment procedures; incidents spread unchecked until resolved.','maturity_2'=>'Ad hoc containment occurs but without documented procedures or pre-authorized actions.','maturity_3'=>'Documented containment procedures with pre-authorized actions, network isolation capabilities, and rapid response tools.','maturity_4'=>'Automated containment with SOAR playbooks, one-click isolation, and pre-approved containment actions for common scenarios.','control_examples'=>'Examples: Containment procedure document, Network isolation capability evidence, Pre-authorized action list, Containment timeline records.','sort_order'=>4],
    ['ref'=>'INC-05','question'=>'Does the organization have digital forensic investigation capabilities or access to forensic services?','guidance'=>'Verify forensic capability (internal or contracted) with trained personnel, tools, and evidence preservation procedures. Check chain of custody documentation.','maturity_1'=>'No forensic capability; investigations cannot be conducted.','maturity_2'=>'Basic forensic tools available but staff are not trained and procedures are informal.','maturity_3'=>'Forensic capability with trained personnel, documented procedures, evidence preservation, and chain of custody management.','maturity_4'=>'Advanced forensic lab with automated evidence collection, memory and disk forensics, and integration with legal/compliance teams.','control_examples'=>'Examples: Forensic capability assessment, Trained personnel certifications, Evidence handling procedures, Chain of custody forms.','sort_order'=>5],
    ['ref'=>'INC-06','question'=>'Is a communication plan defined for internal and external notifications during security incidents?','guidance'=>'Check for documented communication templates, stakeholder contact lists, media handling procedures, and regulatory notification requirements with timelines.','maturity_1'=>'No communication plan; notifications are ad hoc during incidents.','maturity_2'=>'Basic contact list exists but communication templates and procedures are not defined.','maturity_3'=>'Comprehensive communication plan with templates, stakeholder lists, media procedures, and regulatory notification timelines.','maturity_4'=>'Automated communication workflows with pre-approved templates, real-time status pages, and integrated stakeholder management.','control_examples'=>'Examples: Communication plan document, Notification templates, Stakeholder contact list, Regulatory notification timeline chart.','sort_order'=>6],
    ['ref'=>'INC-07','question'=>'Is a regulatory breach notification process in place to comply with data breach reporting requirements?','guidance'=>'Verify documented process for determining breach notification requirements per applicable regulations (GDPR 72hr, state laws, HIPAA, etc.) with legal review.','maturity_1'=>'No breach notification process; regulatory requirements unknown.','maturity_2'=>'Awareness of some notification requirements but no formal process or templates.','maturity_3'=>'Documented breach notification process with regulatory requirement matrix, notification templates, legal review, and timeline tracking.','maturity_4'=>'Automated breach assessment with regulatory requirement engine, pre-approved notifications, and integrated regulatory tracking.','control_examples'=>'Examples: Breach notification procedure, Regulatory requirement matrix, Notification templates by jurisdiction, Legal review records.','sort_order'=>7],
    ['ref'=>'INC-08','question'=>'Are post-incident reviews (lessons learned) conducted after significant incidents with improvement actions tracked?','guidance'=>'Look for documented post-incident reviews within 2 weeks of incident closure. Check for root cause analysis, improvement recommendations, and tracked implementation.','maturity_1'=>'No post-incident reviews conducted; same mistakes repeated.','maturity_2'=>'Informal reviews occur for major incidents but findings are not tracked.','maturity_3'=>'Formal post-incident reviews for all significant incidents with root cause analysis, documented improvements, and tracked actions.','maturity_4'=>'Systematic lessons-learned program with trend analysis, process improvement integration, and metrics on recurring incident reduction.','control_examples'=>'Examples: Post-incident review reports, Root cause analysis documents, Improvement action tracker, Trend analysis showing reduction in recurring incidents.','sort_order'=>8],
    ['ref'=>'INC-09','question'=>'Is an incident response team established with clearly defined roles, responsibilities, and contact information?','guidance'=>'Check for named incident response team members with specific roles (incident commander, technical lead, communications, legal). Verify on-call procedures.','maturity_1'=>'No designated incident response team; response is ad hoc.','maturity_2'=>'Some team members are informally assigned but roles are not clearly defined or documented.','maturity_3'=>'Formal IRT with named members, defined roles (commander, technical, communications, legal), on-call rotation, and contact list.','maturity_4'=>'Tiered response team with specialized roles, cross-functional support, regular training, and automated escalation workflows.','control_examples'=>'Examples: IRT roster with roles, On-call schedule, Contact information card, Role-specific procedure documents.','sort_order'=>9],
    ['ref'=>'INC-10','question'=>'Are incident response exercises (tabletop, functional, full-scale) conducted regularly to validate preparedness?','guidance'=>'Verify IR exercises are conducted at least annually with realistic scenarios. Check for participant attendance, exercise outcomes, and improvement actions.','maturity_1'=>'No IR exercises or drills conducted.','maturity_2'=>'Occasional tabletop exercises without structured scenarios or follow-up actions.','maturity_3'=>'Annual tabletop and functional exercises with realistic scenarios, cross-functional participation, and documented improvement actions.','maturity_4'=>'Quarterly exercises of varying types (tabletop, functional, full-scale) with red team integration and continuous improvement program.','control_examples'=>'Examples: Exercise schedule, Scenario documents, Participant attendance records, Exercise after-action reports, Improvement action tracker.','sort_order'=>10],
],

// =========================================================================
// SCM - Supply Chain & Third Party (10 questions)
// =========================================================================
'SCM' => [
    ['ref'=>'SCM-01','question'=>'Does the organization have a formal vendor risk assessment process for evaluating third-party security posture?','guidance'=>'Look for a documented process for assessing vendor security before engagement and periodically. Check assessment questionnaires, risk ratings, and due diligence records.','maturity_1'=>'No vendor risk assessment process; vendors are onboarded without security evaluation.','maturity_2'=>'Informal assessment for some vendors but not standardized or comprehensive.','maturity_3'=>'Formal vendor risk assessment with standardized questionnaires, risk tiering, documented due diligence, and approval workflow.','maturity_4'=>'Automated vendor assessment with continuous monitoring, real-time risk scoring, and integration with procurement.','control_examples'=>'Examples: Vendor assessment questionnaire, Risk rating methodology, Due diligence records, Vendor risk register.','sort_order'=>1],
    ['ref'=>'SCM-02','question'=>'Are security requirements included in vendor contracts, including data protection obligations and right to audit?','guidance'=>'Verify contracts include security requirements, data handling obligations, breach notification, SLAs, and right to audit clauses.','maturity_1'=>'No security clauses in vendor contracts.','maturity_2'=>'Some contracts have basic security language but requirements are not standardized.','maturity_3'=>'Standard security clauses in all vendor contracts including data protection, breach notification, SLAs, and right to audit.','maturity_4'=>'Dynamic contract requirements based on risk tier with automated compliance tracking and penalty enforcement.','control_examples'=>'Examples: Standard security contract clauses, Data processing agreements, Right to audit provisions, Breach notification requirements.','sort_order'=>2],
    ['ref'=>'SCM-03','question'=>'Is ongoing vendor security monitoring performed beyond initial assessment, including periodic reassessments?','guidance'=>'Check for periodic vendor reassessment schedules, continuous monitoring services, and processes for tracking changes in vendor security posture.','maturity_1'=>'No ongoing monitoring; vendors are assessed once and never re-evaluated.','maturity_2'=>'Annual reassessments for some critical vendors but no continuous monitoring.','maturity_3'=>'Risk-tiered reassessment schedule (annual for high-risk, biennial for others) with continuous monitoring services for critical vendors.','maturity_4'=>'Real-time vendor risk monitoring with automated security scoring, threat intelligence integration, and instant risk alerts.','control_examples'=>'Examples: Vendor reassessment schedule, Continuous monitoring dashboard, Security scorecard trends, Vendor risk change alerts.','sort_order'=>3],
    ['ref'=>'SCM-04','question'=>'Are supply chain security controls implemented to protect against compromise through vendors and partners?','guidance'=>'Look for controls addressing software supply chain (SBOM, code signing), hardware supply chain integrity, and vendor access restrictions.','maturity_1'=>'No supply chain security controls; vendor-provided software/hardware is trusted implicitly.','maturity_2'=>'Basic controls exist for some supply chain risks but not comprehensive.','maturity_3'=>'Supply chain controls including SBOM review, code signing verification, hardware integrity checks, and vendor access restrictions.','maturity_4'=>'Comprehensive supply chain risk program with automated SBOM analysis, zero-trust vendor access, and continuous integrity monitoring.','control_examples'=>'Examples: SBOM for critical software, Code signing verification records, Hardware integrity procedures, Vendor access restriction policy.','sort_order'=>4],
    ['ref'=>'SCM-05','question'=>'Is sub-processor and fourth-party risk management addressed in the vendor management program?','guidance'=>'Verify that critical vendors disclose sub-processors and that fourth-party risks are assessed. Check contract clauses requiring sub-processor notification.','maturity_1'=>'No visibility into vendor sub-processors or fourth-party risks.','maturity_2'=>'Some awareness of key sub-processors but no formal management process.','maturity_3'=>'Sub-processor disclosure required in contracts, fourth-party risk assessed for critical vendors, and change notification procedures.','maturity_4'=>'Automated sub-processor tracking with risk chain analysis and dynamic fourth-party risk scoring.','control_examples'=>'Examples: Sub-processor disclosure contract clause, Sub-processor inventory, Fourth-party risk assessment records, Change notification evidence.','sort_order'=>5],
    ['ref'=>'SCM-06','question'=>'Are vendor access controls implemented to restrict third-party access to only necessary systems and data?','guidance'=>'Check that vendor access is limited by scope, time-bound, monitored, and uses dedicated accounts. Verify MFA and privileged access controls for vendor connections.','maturity_1'=>'Vendors have unrestricted access to internal systems with shared credentials.','maturity_2'=>'Some vendor access restrictions exist but are not consistently enforced.','maturity_3'=>'Vendor access restricted to required systems, time-bound, using dedicated accounts with MFA, and monitored/logged.','maturity_4'=>'Just-in-time vendor access with session recording, automated deprovisioning, and risk-based access controls.','control_examples'=>'Examples: Vendor access request/approval records, Dedicated vendor account list, MFA enforcement evidence, Vendor session logs.','sort_order'=>6],
    ['ref'=>'SCM-07','question'=>'Are SLAs monitored for vendor compliance with security requirements and service delivery standards?','guidance'=>'Verify SLA monitoring processes, regular reporting from vendors, and consequences for SLA violations. Check vendor performance scorecards.','maturity_1'=>'No SLA monitoring for vendor security or service delivery.','maturity_2'=>'SLAs exist but monitoring is informal and consequences are not enforced.','maturity_3'=>'SLA monitoring with regular vendor reporting, performance scorecards, documented violations, and escalation procedures.','maturity_4'=>'Automated SLA monitoring with real-time dashboards, automated alerts, and contractual penalty tracking.','control_examples'=>'Examples: SLA monitoring reports, Vendor performance scorecards, SLA violation records, Vendor review meeting minutes.','sort_order'=>7],
    ['ref'=>'SCM-08','question'=>'Is fourth-party (sub-vendor) risk management addressed to understand dependencies in the supply chain?','guidance'=>'Check for visibility into critical vendor dependencies, concentration risk analysis, and requirements for vendors to manage their own third-party risks.','maturity_1'=>'No awareness of fourth-party dependencies or concentration risks.','maturity_2'=>'Some understanding of major vendor dependencies but no formal analysis.','maturity_3'=>'Fourth-party risk mapping for critical vendors, concentration risk analysis, and vendor requirements to manage their third parties.','maturity_4'=>'Automated dependency mapping with multi-tier risk visualization and real-time concentration risk monitoring.','control_examples'=>'Examples: Fourth-party dependency map, Concentration risk analysis, Vendor third-party management requirements, Supply chain risk report.','sort_order'=>8],
    ['ref'=>'SCM-09','question'=>'Are vendor incident notification requirements defined with specific timeframes and communication channels?','guidance'=>'Verify contracts require vendors to notify of security incidents within defined timeframes (e.g., 24-72 hours). Check incident communication procedures and escalation.','maturity_1'=>'No vendor incident notification requirements in place.','maturity_2'=>'Some contracts mention incident notification but timeframes and channels are vague.','maturity_3'=>'Defined incident notification requirements in all vendor contracts with specific timeframes, channels, and escalation procedures.','maturity_4'=>'Automated vendor incident intake with integration into organizational incident response and automated impact assessment.','control_examples'=>'Examples: Contract incident notification clauses, Vendor incident communication plan, Notification timeline requirements, Historical vendor incident records.','sort_order'=>9],
    ['ref'=>'SCM-10','question'=>'Are cloud service provider security controls assessed including certifications, shared responsibility, and configuration?','guidance'=>'Verify CSP security assessment including SOC 2 reports, shared responsibility model documentation, and cloud configuration security reviews.','maturity_1'=>'No assessment of cloud service provider security or shared responsibility.','maturity_2'=>'CSP certifications reviewed but shared responsibility and configuration security not addressed.','maturity_3'=>'CSP security assessed with SOC 2 review, shared responsibility documented, configuration security reviewed, and regular reassessment.','maturity_4'=>'Continuous CSP security monitoring with automated configuration compliance, multi-cloud visibility, and shared responsibility enforcement.','control_examples'=>'Examples: CSP SOC 2 report review records, Shared responsibility matrix, Cloud configuration review results, CSP reassessment schedule.','sort_order'=>10],
],

// =========================================================================
// PHY - Physical & Environmental (8 questions)
// =========================================================================
'PHY' => [
    ['ref'=>'PHY-01','question'=>'Are physical access controls (badges, biometrics, PINs) implemented to restrict entry to facilities and sensitive areas?','guidance'=>'Verify physical access control systems at facility entry points and for sensitive areas (server rooms, wiring closets). Check access logs and review processes.','maturity_1'=>'No physical access controls; facilities are open or use basic locks only.','maturity_2'=>'Badge access at main entry but sensitive areas may not have additional controls.','maturity_3'=>'Multi-layer physical access with badge/biometric for building and additional controls for sensitive areas, access logs, and regular reviews.','maturity_4'=>'Integrated physical-logical access with real-time monitoring, anti-tailgating technology, and behavioral analytics.','control_examples'=>'Examples: Access control system configuration, Badge reader placement map, Access log reports, Sensitive area access review records.','sort_order'=>1],
    ['ref'=>'PHY-02','question'=>'Are data center and server room security controls implemented including restricted access, monitoring, and environmental protection?','guidance'=>'Check data center access restrictions, visitor procedures, temperature/humidity monitoring, fire suppression, and water detection systems.','maturity_1'=>'Server rooms have no dedicated security controls or environmental monitoring.','maturity_2'=>'Basic lock and key for server rooms but limited environmental monitoring.','maturity_3'=>'Restricted access with logging, environmental monitoring (temperature, humidity, water), fire suppression, and UPS.','maturity_4'=>'Fully monitored data center with redundant environmental controls, automated alerting, and predictive maintenance.','control_examples'=>'Examples: Server room access log, Environmental monitoring dashboard, Fire suppression system maintenance records, UPS test results.','sort_order'=>2],
    ['ref'=>'PHY-03','question'=>'Are environmental controls (HVAC, fire suppression, water detection) maintained and tested for facility protection?','guidance'=>'Verify environmental controls are professionally maintained, regularly tested, and documented. Check for redundancy in critical systems.','maturity_1'=>'No environmental controls or maintenance records.','maturity_2'=>'Basic HVAC and fire systems exist but maintenance is irregular and testing undocumented.','maturity_3'=>'Professional maintenance schedule, regular testing of fire suppression and HVAC, documented results, and redundancy for critical systems.','maturity_4'=>'Smart building management with predictive analytics, automated alerting, and integrated environmental monitoring.','control_examples'=>'Examples: HVAC maintenance schedule and records, Fire suppression test certificates, Water detection sensor placement map, Environmental alert logs.','sort_order'=>3],
    ['ref'=>'PHY-04','question'=>'Is a visitor management process in place to control and monitor non-employee access to facilities?','guidance'=>'Check for visitor registration, identification verification, escort requirements for sensitive areas, and visitor log retention.','maturity_1'=>'No visitor management; visitors can enter and move freely.','maturity_2'=>'Basic visitor sign-in exists but no escort requirements or consistent enforcement.','maturity_3'=>'Formal visitor management with registration, ID verification, badges, escort requirements for sensitive areas, and retained logs.','maturity_4'=>'Digital visitor management with pre-registration, automated badge printing, real-time tracking, and integration with access control.','control_examples'=>'Examples: Visitor management policy, Visitor sign-in log, Visitor badge samples, Escort requirement documentation.','sort_order'=>4],
    ['ref'=>'PHY-05','question'=>'Is video surveillance (CCTV) deployed at facility entry/exit points and sensitive areas with appropriate retention?','guidance'=>'Verify camera placement at key locations, recording retention period, access controls to footage, and regular system maintenance.','maturity_1'=>'No video surveillance in place.','maturity_2'=>'Some cameras at main entrance but coverage is incomplete and retention may be short.','maturity_3'=>'CCTV at all entry/exit points and sensitive areas with minimum 30-day retention, access-controlled footage, and regular maintenance.','maturity_4'=>'AI-driven video analytics with anomaly detection, integration with access control, and automated incident flagging.','control_examples'=>'Examples: Camera placement map, Recording retention policy, Footage access log, Camera maintenance records.','sort_order'=>5],
    ['ref'=>'PHY-06','question'=>'Is secure disposal of equipment and media performed to prevent data recovery from decommissioned assets?','guidance'=>'Look for documented disposal procedures including data wiping, degaussing, or physical destruction. Check for certificates of destruction and chain of custody.','maturity_1'=>'Equipment disposed without data sanitization; data recovery risk exists.','maturity_2'=>'Some disposal procedures exist but are inconsistently applied and undocumented.','maturity_3'=>'Documented disposal procedures with approved methods (NIST 800-88), certificates of destruction, and chain of custody tracking.','maturity_4'=>'Automated asset lifecycle management with integrated disposal tracking, verified destruction, and comprehensive audit trail.','control_examples'=>'Examples: Data sanitization procedure, Certificates of destruction, Chain of custody records, NIST 800-88 compliance evidence.','sort_order'=>6],
    ['ref'=>'PHY-07','question'=>'Is a clean desk and clear screen policy implemented and enforced to protect sensitive information?','guidance'=>'Check for documented clean desk policy requiring sensitive documents to be secured, screens locked when unattended, and whiteboards cleared.','maturity_1'=>'No clean desk policy; sensitive documents left unattended openly.','maturity_2'=>'Policy exists but enforcement is minimal and compliance not monitored.','maturity_3'=>'Clean desk policy enforced with regular spot checks, automatic screen lock, and secure storage available for all staff.','maturity_4'=>'Smart office integration with automated screen lock, document presence detection, and compliance analytics.','control_examples'=>'Examples: Clean desk policy, Spot check results, Auto screen lock configuration, Secure storage availability evidence.','sort_order'=>7],
    ['ref'=>'PHY-08','question'=>'Are power and network cabling secured to prevent unauthorized access, interference, or damage?','guidance'=>'Verify cabling is secured in locked conduits or cable trays, labeled, documented, and protected from physical damage or tampering.','maturity_1'=>'Cables are unsecured, unlabeled, and exposed to potential tampering.','maturity_2'=>'Some cable management exists but inconsistently applied.','maturity_3'=>'Cables secured in conduits/trays, labeled, documented, and protected from unauthorized access and environmental damage.','maturity_4'=>'Intelligent cabling management with fiber optic security monitoring, automated topology mapping, and tamper detection.','control_examples'=>'Examples: Cable management photos, Cabling documentation, Conduit/tray installation evidence, Network port security configuration.','sort_order'=>8],
],

// =========================================================================
// HRS - Human Resources Security (10 questions)
// =========================================================================
'HRS' => [
    ['ref'=>'HRS-01','question'=>'Are background verification and screening checks performed on all employees before granting access to information systems?','guidance'=>'Verify background checks are conducted during hiring, including criminal history, employment verification, and reference checks appropriate to the role.','maturity_1'=>'No background checks performed on new hires.','maturity_2'=>'Background checks for some roles but not consistently applied to all positions.','maturity_3'=>'Background checks required for all employees before system access, with enhanced checks for privileged roles, documented and retained.','maturity_4'=>'Continuous background monitoring with risk-based screening levels and automated re-screening for role changes.','control_examples'=>'Examples: Background check policy, Completed check records, Enhanced screening criteria for privileged roles, Retention records.','sort_order'=>1],
    ['ref'=>'HRS-02','question'=>'Is a security awareness training program implemented for all employees with regular updates and phishing simulations?','guidance'=>'Check for mandatory annual training, phishing simulation program, training completion tracking, and consequences for repeated failures.','maturity_1'=>'No security awareness training provided to employees.','maturity_2'=>'Basic annual training exists but without phishing simulations or completion enforcement.','maturity_3'=>'Mandatory annual training with monthly phishing simulations, tracked completion rates, and remedial training for failures.','maturity_4'=>'Adaptive training with role-based content, gamification, continuous micro-learning, and behavioral risk scoring per employee.','control_examples'=>'Examples: Training program overview, Completion rate reports, Phishing simulation results, Remedial training records.','sort_order'=>2],
    ['ref'=>'HRS-03','question'=>'Is role-specific security training provided to staff in specialized positions such as developers, administrators, and incident responders?','guidance'=>'Verify that staff in security-critical roles receive specialized training beyond general awareness (secure coding, system administration security, IR procedures).','maturity_1'=>'No role-specific security training; all staff receive the same generic training.','maturity_2'=>'Some specialized training exists but coverage is incomplete.','maturity_3'=>'Role-specific training programs for developers, admins, and IR staff with defined curricula, certification support, and tracked completion.','maturity_4'=>'Continuous skill development with hands-on labs, CTF exercises, industry certifications funded, and competency assessments.','control_examples'=>'Examples: Role-specific training curriculum, Training completion records by role, Certification tracking, Hands-on lab participation records.','sort_order'=>3],
    ['ref'=>'HRS-04','question'=>'Are security procedures integrated into the employee onboarding process including acceptable use acknowledgment?','guidance'=>'Check that new hire onboarding includes security training, acceptable use policy acknowledgment, NDA signing, and access provisioning per role.','maturity_1'=>'No security steps in the onboarding process.','maturity_2'=>'Some security onboarding exists but it is informal and not consistently followed.','maturity_3'=>'Formal security onboarding checklist with training, AUP acknowledgment, NDA, role-based access provisioning, and HR-IT coordination.','maturity_4'=>'Automated onboarding workflow with integrated security training, automated access provisioning, and completion verification.','control_examples'=>'Examples: Onboarding security checklist, AUP acknowledgment forms, NDA records, Access provisioning request/completion evidence.','sort_order'=>4],
    ['ref'=>'HRS-05','question'=>'Are security procedures integrated into the employee offboarding process to ensure timely access revocation?','guidance'=>'Verify offboarding checklist includes access revocation within 24 hours, device return, data transfer procedures, and exit interview covering security obligations.','maturity_1'=>'No offboarding security procedures; terminated users retain access for extended periods.','maturity_2'=>'Basic offboarding exists but access revocation may be delayed and inconsistent.','maturity_3'=>'Formal offboarding with access revoked within 24 hours, devices returned, data procedures followed, and verified completion.','maturity_4'=>'Automated offboarding triggered by HR system with instant access revocation, automated device wipe, and compliance verification.','control_examples'=>'Examples: Offboarding checklist, Access revocation timeline evidence, Device return log, Exit interview records.','sort_order'=>5],
    ['ref'=>'HRS-06','question'=>'Is an acceptable use policy defined and acknowledged by all employees covering use of organizational IT resources?','guidance'=>'Look for AUP covering email, internet, social media, personal devices, and company assets. Verify annual acknowledgment by all employees.','maturity_1'=>'No acceptable use policy exists.','maturity_2'=>'AUP exists but may be outdated or not consistently acknowledged by all employees.','maturity_3'=>'Comprehensive AUP covering all IT resources, annually acknowledged by all employees, with documented enforcement procedures.','maturity_4'=>'Dynamic AUP with automated acknowledgment tracking, policy violation detection, and regular updates based on emerging risks.','control_examples'=>'Examples: Acceptable use policy document, Employee acknowledgment records, Enforcement procedure documentation, Annual distribution evidence.','sort_order'=>6],
    ['ref'=>'HRS-07','question'=>'Are non-disclosure and confidentiality agreements signed by all employees, contractors, and third parties with access to sensitive information?','guidance'=>'Verify NDAs are signed during onboarding and maintained on file. Check that NDAs cover post-employment obligations and are updated for role changes.','maturity_1'=>'No NDAs or confidentiality agreements in place.','maturity_2'=>'NDAs used for some roles but not consistently required or maintained.','maturity_3'=>'NDAs required for all employees, contractors, and third parties with access to sensitive data, signed and retained on file.','maturity_4'=>'Automated NDA management with role-based terms, electronic signatures, renewal tracking, and compliance monitoring.','control_examples'=>'Examples: NDA template, Signed NDA records, Contractor NDA evidence, NDA tracking log.','sort_order'=>7],
    ['ref'=>'HRS-08','question'=>'Is a disciplinary process in place for addressing security policy violations and non-compliance?','guidance'=>'Check for documented disciplinary procedures for security violations, clear escalation path, and evidence of consistent enforcement.','maturity_1'=>'No disciplinary process for security violations.','maturity_2'=>'Informal consequences exist but are not documented or consistently applied.','maturity_3'=>'Formal disciplinary process documented in HR policy with graduated consequences, consistent enforcement, and documented outcomes.','maturity_4'=>'Integrated violation tracking with automated incident-to-HR workflow, trend analysis, and proactive intervention for at-risk employees.','control_examples'=>'Examples: Disciplinary policy for security violations, Graduated consequence matrix, Violation tracking records, HR investigation procedures.','sort_order'=>8],
    ['ref'=>'HRS-09','question'=>'Does the organization promote a positive security culture where employees feel empowered to report security concerns?','guidance'=>'Look for anonymous reporting mechanisms, security champion programs, positive reinforcement for reporting, and evidence of a no-blame culture for good-faith reports.','maturity_1'=>'No security culture initiatives; employees fear reporting security concerns.','maturity_2'=>'Some awareness of security culture but no formal programs or anonymous reporting.','maturity_3'=>'Active security culture program with anonymous reporting, security champions, recognition programs, and no-blame reporting policy.','maturity_4'=>'Data-driven security culture measurement with regular surveys, behavioral analytics, and continuous culture improvement program.','control_examples'=>'Examples: Anonymous reporting mechanism, Security champion program documentation, Recognition program records, Security culture survey results.','sort_order'=>9],
    ['ref'=>'HRS-10','question'=>'Are contractor and temporary staff subject to the same security requirements as permanent employees?','guidance'=>'Verify that contractors undergo background checks, receive security training, sign NDAs, and have access limited to their assignment scope with timely offboarding.','maturity_1'=>'Contractors have unrestricted access with no security requirements.','maturity_2'=>'Some requirements for contractors but enforcement varies and gaps exist.','maturity_3'=>'Contractors subject to background checks, security training, NDAs, time-bound access, and formal offboarding matching employee standards.','maturity_4'=>'Automated contractor lifecycle management with integrated security requirements, continuous compliance, and automated access expiration.','control_examples'=>'Examples: Contractor security requirements policy, Contractor background check records, Training completion evidence, Time-bound access configuration.','sort_order'=>10],
],

// =========================================================================
// BCP - Business Continuity (10 questions)
// =========================================================================
'BCP' => [
    ['ref'=>'BCP-01','question'=>'Has the organization developed and maintained a business continuity plan (BCP) covering critical business functions?','guidance'=>'Look for a documented BCP that identifies critical functions, dependencies, and procedures for maintaining operations during disruptions. Verify management approval.','maturity_1'=>'No business continuity plan exists.','maturity_2'=>'Basic BCP exists but may be incomplete, outdated, or not tested.','maturity_3'=>'Comprehensive BCP covering all critical functions, approved by management, with defined procedures and annual review.','maturity_4'=>'Dynamic BCP integrated with operational resilience framework, automated dependency mapping, and continuous improvement cycle.','control_examples'=>'Examples: BCP document, Management approval records, Critical function inventory, Annual review records.','sort_order'=>1],
    ['ref'=>'BCP-02','question'=>'Is a disaster recovery plan (DRP) documented for IT systems with defined recovery procedures and responsibilities?','guidance'=>'Verify DRP covers critical IT systems with step-by-step recovery procedures, responsibilities, and communication plans. Check for regular updates.','maturity_1'=>'No disaster recovery plan exists for IT systems.','maturity_2'=>'Basic DRP exists but lacks detail, assigned responsibilities, or regular updates.','maturity_3'=>'Comprehensive DRP with detailed procedures for all critical systems, assigned responsibilities, and tested annually.','maturity_4'=>'Automated DR with infrastructure-as-code recovery, runbook automation, and orchestrated failover/failback procedures.','control_examples'=>'Examples: DR plan document, System recovery procedures, Responsibility matrix, DR test results.','sort_order'=>2],
    ['ref'=>'BCP-03','question'=>'Has a business impact analysis (BIA) been conducted to identify critical processes, dependencies, and acceptable downtime?','guidance'=>'Check for documented BIA identifying critical business processes, maximum tolerable downtime, dependencies, and resource requirements for recovery.','maturity_1'=>'No BIA conducted; critical process priorities are unknown.','maturity_2'=>'Informal understanding of critical processes but no documented BIA.','maturity_3'=>'Formal BIA completed identifying all critical processes, MAO/MTPD values, dependencies, and resource requirements. Updated annually.','maturity_4'=>'Dynamic BIA with automated dependency mapping, real-time criticality assessment, and integrated with risk management.','control_examples'=>'Examples: BIA report, Critical process ranking, Dependency mapping, MAO/MTPD documentation, Annual update records.','sort_order'=>3],
    ['ref'=>'BCP-04','question'=>'Are recovery time objectives (RTO) and recovery point objectives (RPO) defined and tested for critical systems?','guidance'=>'Verify RTO/RPO are defined for each critical system based on BIA results. Check that DR tests validate these objectives are achievable.','maturity_1'=>'No RTO/RPO defined for any systems.','maturity_2'=>'RTO/RPO defined for some systems but not tested or validated.','maturity_3'=>'RTO/RPO defined for all critical systems based on BIA, validated through regular DR testing, and gaps remediated.','maturity_4'=>'Automated RTO/RPO validation with continuous DR readiness testing and dynamic adjustment based on system changes.','control_examples'=>'Examples: RTO/RPO table for critical systems, DR test results showing recovery times, Gap remediation records, BIA alignment documentation.','sort_order'=>4],
    ['ref'=>'BCP-05','question'=>'Is a comprehensive backup strategy implemented with regular testing and off-site or cloud storage?','guidance'=>'Verify backup policies cover all critical data, backups are encrypted, stored off-site/cloud, and restoration is tested regularly. Check for immutable backup capabilities.','maturity_1'=>'No backup strategy or backups are unreliable and untested.','maturity_2'=>'Backups exist but testing is infrequent and off-site storage may be incomplete.','maturity_3'=>'Comprehensive backup strategy with 3-2-1 rule, encryption, off-site/cloud storage, quarterly restore testing, and documented procedures.','maturity_4'=>'Immutable backups with continuous validation, automated integrity checking, instant recovery capability, and ransomware protection.','control_examples'=>'Examples: Backup policy and schedule, 3-2-1 compliance evidence, Restore test results, Off-site storage configuration, Encryption evidence.','sort_order'=>5],
    ['ref'=>'BCP-06','question'=>'Is a crisis communication plan in place for notifying stakeholders, customers, and regulators during major disruptions?','guidance'=>'Check for documented communication plan with stakeholder contact lists, message templates, communication channels, and spokesperson assignments.','maturity_1'=>'No crisis communication plan; stakeholders are notified ad hoc.','maturity_2'=>'Basic contact lists exist but communication templates and procedures are not defined.','maturity_3'=>'Crisis communication plan with templates, stakeholder lists, designated spokespersons, and defined channels for different audiences.','maturity_4'=>'Automated crisis communication with multi-channel distribution, real-time status pages, and pre-approved message templates.','control_examples'=>'Examples: Crisis communication plan, Stakeholder contact list, Message templates, Spokesperson assignments, Status page configuration.','sort_order'=>6],
    ['ref'=>'BCP-07','question'=>'Are alternate processing sites or cloud failover capabilities available for critical systems?','guidance'=>'Verify alternate recovery sites exist (hot/warm/cold site, cloud DR region, or DRaaS). Check failover testing records and connectivity verification.','maturity_1'=>'No alternate processing capability; single point of failure for all systems.','maturity_2'=>'Some cloud redundancy exists but failover is not tested or documented.','maturity_3'=>'Alternate processing sites or cloud DR configured for critical systems with tested failover and documented procedures.','maturity_4'=>'Active-active multi-region deployment with automated failover, zero-RPO capabilities, and continuous failover testing.','control_examples'=>'Examples: DR site documentation, Cloud DR region configuration, Failover test results, Connectivity verification records.','sort_order'=>7],
    ['ref'=>'BCP-08','question'=>'Are BCP and DR plans tested at least annually through tabletop exercises, functional tests, or full-scale drills?','guidance'=>'Verify regular testing of BCP/DR plans with different exercise types. Check participant attendance, test results, and improvement actions from findings.','maturity_1'=>'No BCP/DR testing performed.','maturity_2'=>'Testing occurs sporadically without structured exercises or follow-up.','maturity_3'=>'Annual BCP/DR testing with varied exercise types, documented results, identified gaps, and tracked improvement actions.','maturity_4'=>'Quarterly testing with automated DR validation, chaos engineering, and continuous improvement program.','control_examples'=>'Examples: Test schedule and calendar, Exercise reports, Participant attendance records, Gap identification and remediation tracking.','sort_order'=>8],
    ['ref'=>'BCP-09','question'=>'Does the organization have plans to address pandemic, workforce disruption, or remote work continuity scenarios?','guidance'=>'Check for plans addressing extended remote work, key person dependencies, workforce health events, and ability to maintain operations with reduced staffing.','maturity_1'=>'No plans for workforce disruption scenarios.','maturity_2'=>'Lessons learned from COVID-19 exist but not formalized into plans.','maturity_3'=>'Documented plans for remote work continuity, key person dependencies, succession planning, and workforce disruption scenarios.','maturity_4'=>'Resilient workforce model with distributed operations, cross-trained staff, automated processes, and regular disruption simulations.','control_examples'=>'Examples: Remote work continuity plan, Key person dependency analysis, Succession plan, Cross-training records.','sort_order'=>9],
    ['ref'=>'BCP-10','question'=>'Are supply chain and vendor continuity risks addressed in the business continuity program?','guidance'=>'Verify BCP addresses critical vendor dependencies, alternate vendor identification, and vendor BCP/DR validation. Check for vendor continuity in contracts.','maturity_1'=>'No consideration of supply chain continuity in BCP.','maturity_2'=>'Key vendor dependencies are known but no alternate vendor plans exist.','maturity_3'=>'Critical vendor dependencies mapped, alternate vendors identified, vendor BCP/DR validated, and continuity clauses in contracts.','maturity_4'=>'Automated vendor continuity monitoring with real-time risk alerts, pre-qualified alternate vendors, and integrated supply chain resilience.','control_examples'=>'Examples: Critical vendor dependency map, Alternate vendor list, Vendor BCP validation records, Continuity contract clauses.','sort_order'=>10],
],

// =========================================================================
// CRY - Cryptography & Key Management (8 questions)
// =========================================================================
'CRY' => [
    ['ref'=>'CRY-01','question'=>'Has the organization defined a cryptographic policy specifying approved algorithms, key lengths, and use cases?','guidance'=>'Look for a documented crypto policy specifying approved algorithms (AES-256, RSA-2048+, SHA-256+), prohibited algorithms (DES, MD5, SHA-1), and use case requirements.','maturity_1'=>'No cryptographic policy; encryption decisions are ad hoc.','maturity_2'=>'Some encryption standards exist but not comprehensively documented or enforced.','maturity_3'=>'Documented cryptographic policy with approved algorithms, key lengths, prohibited ciphers, and use-case requirements.','maturity_4'=>'Crypto-agile policy with automated algorithm inventory, quantum-readiness planning, and continuous cipher suite monitoring.','control_examples'=>'Examples: Cryptographic policy document, Approved algorithm list, Prohibited cipher list, Use-case requirements matrix.','sort_order'=>1],
    ['ref'=>'CRY-02','question'=>'Are cryptographic keys generated using approved methods with sufficient entropy and randomness?','guidance'=>'Verify key generation uses approved random number generators, appropriate key lengths, and secure generation environments. Check for FIPS 140-2/3 compliance where required.','maturity_1'=>'No standards for key generation; keys may be weak or predictable.','maturity_2'=>'Keys are generated with standard tools but without verified entropy or documented procedures.','maturity_3'=>'Key generation follows documented procedures using CSPRNG, appropriate key lengths, and FIPS-validated modules where required.','maturity_4'=>'Hardware-based key generation with HSMs, quantum-resistant algorithms being evaluated, and automated key strength verification.','control_examples'=>'Examples: Key generation procedure, FIPS 140-2/3 certificate, HSM configuration, Key strength verification records.','sort_order'=>2],
    ['ref'=>'CRY-03','question'=>'Are cryptographic keys stored securely with appropriate access controls and protection from unauthorized access?','guidance'=>'Check that keys are stored in key management systems, HSMs, or secure vaults. Verify access to key material is restricted and logged.','maturity_1'=>'Keys stored in plain text in files, code, or databases without protection.','maturity_2'=>'Keys stored with some protection but may be accessible to too many people.','maturity_3'=>'Keys stored in dedicated KMS or HSM with strict access controls, audit logging, and separation of duties.','maturity_4'=>'Hardware-backed key storage with FIPS 140-3 Level 3 HSMs, zero-knowledge key management, and automated access auditing.','control_examples'=>'Examples: KMS/HSM configuration, Key access control list, Key access audit logs, Separation of duties evidence.','sort_order'=>3],
    ['ref'=>'CRY-04','question'=>'Is a key rotation and retirement policy implemented with defined schedules for all cryptographic keys?','guidance'=>'Verify key rotation schedules exist for all key types (encryption, signing, authentication). Check that retired keys are securely destroyed and rotation is documented.','maturity_1'=>'No key rotation; keys are used indefinitely without change.','maturity_2'=>'Some key rotation occurs but schedules are informal and inconsistent.','maturity_3'=>'Defined rotation schedules for all key types, automated rotation where possible, and documented key retirement with secure destruction.','maturity_4'=>'Fully automated key lifecycle management with zero-downtime rotation, compliance monitoring, and crypto-period enforcement.','control_examples'=>'Examples: Key rotation schedule, Automated rotation configuration, Key retirement records, Secure destruction evidence.','sort_order'=>4],
    ['ref'=>'CRY-05','question'=>'Is a PKI or certificate management system in place to manage digital certificates throughout their lifecycle?','guidance'=>'Check for certificate inventory, automated renewal, expiration monitoring, and revocation procedures. Verify certificates use appropriate algorithms and key lengths.','maturity_1'=>'No certificate management; certificates expire unexpectedly causing outages.','maturity_2'=>'Basic certificate tracking exists but relies on manual monitoring and renewal.','maturity_3'=>'Certificate management system with automated discovery, expiration monitoring, renewal workflows, and revocation procedures.','maturity_4'=>'Fully automated certificate lifecycle with auto-renewal, short-lived certificates, and integration with DevOps pipelines.','control_examples'=>'Examples: Certificate inventory, Expiration monitoring dashboard, Automated renewal configuration, Revocation procedure documentation.','sort_order'=>5],
    ['ref'=>'CRY-06','question'=>'Are TLS/SSL configurations maintained at current standards with deprecated protocols and cipher suites disabled?','guidance'=>'Verify TLS 1.2+ is enforced, TLS 1.0/1.1 disabled, weak cipher suites removed, and HSTS enabled. Check for regular TLS configuration scanning.','maturity_1'=>'Deprecated TLS versions and weak ciphers in use; no configuration management.','maturity_2'=>'TLS 1.2 used for some services but legacy configurations may persist.','maturity_3'=>'TLS 1.2+ enforced everywhere, weak ciphers disabled, HSTS enabled, and regular configuration scanning with remediation.','maturity_4'=>'TLS 1.3 preferred, automated cipher suite management, continuous scanning, and forward secrecy enforced on all endpoints.','control_examples'=>'Examples: TLS configuration scan results (SSL Labs), Cipher suite configuration, HSTS header evidence, Deprecated protocol disable records.','sort_order'=>6],
    ['ref'=>'CRY-07','question'=>'Are only approved and current encryption algorithms used, with a process to identify and replace deprecated algorithms?','guidance'=>'Check for an algorithm inventory across all systems and applications. Verify deprecated algorithms (DES, 3DES, MD5, SHA-1 for signing) are identified and remediated.','maturity_1'=>'No awareness of which algorithms are in use; deprecated algorithms likely present.','maturity_2'=>'Some deprecated algorithms identified but remediation is incomplete.','maturity_3'=>'Algorithm inventory maintained, deprecated algorithms identified with remediation plans, and new deployments use only approved algorithms.','maturity_4'=>'Automated cryptographic discovery with continuous algorithm monitoring, quantum-readiness assessment, and crypto-agility planning.','control_examples'=>'Examples: Cryptographic algorithm inventory, Deprecated algorithm findings, Remediation plan and progress, Approved algorithm enforcement policy.','sort_order'=>7],
    ['ref'=>'CRY-08','question'=>'Are hardware security modules (HSMs) or equivalent used for protecting high-value cryptographic keys?','guidance'=>'Where applicable, verify HSMs are used for root CA keys, payment processing, and other high-value key operations. Check FIPS certification and access controls.','maturity_1'=>'No HSMs; high-value keys stored in software without hardware protection.','maturity_2'=>'HSMs considered but not implemented; high-value keys in software-based vaults.','maturity_3'=>'HSMs deployed for high-value keys with FIPS 140-2/3 certification, restricted access, and documented procedures.','maturity_4'=>'Cloud HSMs or on-premise HSMs with automated key operations, high availability, and integrated with all critical cryptographic processes.','control_examples'=>'Examples: HSM deployment documentation, FIPS certification, Access control records, HSM audit logs.','sort_order'=>8],
],

// =========================================================================
// CMP - Compliance & Assurance (9 questions)
// =========================================================================
'CMP' => [
    ['ref'=>'CMP-01','question'=>'Is a comprehensive inventory of applicable regulatory and compliance requirements maintained and current?','guidance'=>'Verify a register of all applicable regulations, standards, and contractual obligations is maintained with assigned owners and compliance status tracking.','maturity_1'=>'No compliance requirement inventory; regulatory obligations are unknown.','maturity_2'=>'Some regulations are tracked but the inventory is incomplete and not regularly updated.','maturity_3'=>'Complete compliance requirement register with assigned owners, mapped controls, compliance status tracking, and annual updates.','maturity_4'=>'Automated regulatory change monitoring with impact analysis, automated control mapping, and real-time compliance status.','control_examples'=>'Examples: Compliance requirement register, Regulatory mapping matrix, Owner assignments, Compliance status dashboard.','sort_order'=>1],
    ['ref'=>'CMP-02','question'=>'Is an internal audit program established with regular audits of security controls and compliance?','guidance'=>'Check for an internal audit plan, qualified auditors, documented findings, and remediation tracking. Verify audit scope covers security controls and compliance.','maturity_1'=>'No internal audit program for security or compliance.','maturity_2'=>'Occasional audits occur but without a formal plan or consistent methodology.','maturity_3'=>'Formal internal audit program with annual plan, qualified auditors, documented findings, and tracked remediation.','maturity_4'=>'Continuous auditing with automated control testing, real-time compliance monitoring, and risk-based audit prioritization.','control_examples'=>'Examples: Annual audit plan, Audit reports, Auditor qualifications, Finding remediation tracker.','sort_order'=>2],
    ['ref'=>'CMP-03','question'=>'Is external audit management in place for third-party assessments, certifications, and regulatory examinations?','guidance'=>'Verify processes for managing external audits including preparation, evidence collection, finding remediation, and certification maintenance.','maturity_1'=>'No external audit management; audits are chaotic and poorly coordinated.','maturity_2'=>'Basic external audit coordination exists but evidence collection and preparation are ad hoc.','maturity_3'=>'Formal external audit management with preparation checklists, evidence repositories, finding tracking, and certification maintenance.','maturity_4'=>'Audit-ready at all times with continuous evidence collection, automated audit portals, and proactive compliance demonstrations.','control_examples'=>'Examples: External audit preparation checklist, Evidence repository, SOC 2 report, Certification maintenance records.','sort_order'=>3],
    ['ref'=>'CMP-04','question'=>'Is compliance monitoring performed continuously or periodically to track adherence to regulatory and policy requirements?','guidance'=>'Check for compliance monitoring processes, automated compliance tools, regular reporting, and escalation procedures for non-compliance.','maturity_1'=>'No compliance monitoring; issues discovered only during audits.','maturity_2'=>'Periodic compliance checks occur but are manual and may miss issues.','maturity_3'=>'Regular compliance monitoring with automated tools, periodic reporting to management, and escalation for non-compliance.','maturity_4'=>'Continuous compliance monitoring with automated control testing, real-time dashboards, and predictive compliance analytics.','control_examples'=>'Examples: Compliance monitoring tool dashboard, Compliance status reports, Non-compliance escalation records, Automated test results.','sort_order'=>4],
    ['ref'=>'CMP-05','question'=>'Is a management review process in place to evaluate the effectiveness of the information security management system?','guidance'=>'Verify management reviews occur at defined intervals (at least annually) covering security performance, risk changes, audit results, and improvement opportunities.','maturity_1'=>'No management review of the security program.','maturity_2'=>'Informal management reviews occur without structured agenda or documented outcomes.','maturity_3'=>'Formal management review at least annually covering performance metrics, risk status, audit results, and documented improvement decisions.','maturity_4'=>'Quarterly management reviews with data-driven decision support, strategic alignment verification, and effectiveness scoring.','control_examples'=>'Examples: Management review meeting minutes, Review agenda, Performance metric reports, Improvement decision records.','sort_order'=>5],
    ['ref'=>'CMP-06','question'=>'Is a corrective and preventive action (CAPA) process in place for addressing audit findings and compliance gaps?','guidance'=>'Check for documented CAPA process with root cause analysis, action plan development, implementation tracking, and effectiveness verification.','maturity_1'=>'No CAPA process; findings are acknowledged but not systematically addressed.','maturity_2'=>'Some corrective actions taken but without root cause analysis or effectiveness verification.','maturity_3'=>'Formal CAPA process with root cause analysis, action plans, assigned owners, implementation tracking, and effectiveness verification.','maturity_4'=>'Automated CAPA workflow with trend analysis, predictive issue identification, and continuous process improvement integration.','control_examples'=>'Examples: CAPA procedure, Root cause analysis records, Action plan tracker, Effectiveness verification evidence.','sort_order'=>6],
    ['ref'=>'CMP-07','question'=>'Is there a process to monitor and respond to changes in applicable laws, regulations, and industry standards?','guidance'=>'Verify the organization monitors regulatory changes through subscriptions, industry groups, or legal counsel. Check for impact assessments and compliance updates.','maturity_1'=>'No monitoring of regulatory changes; organization reacts only when notified of violations.','maturity_2'=>'Informal monitoring through industry contacts but no systematic process.','maturity_3'=>'Systematic regulatory change monitoring with subscriptions, impact assessments, compliance update procedures, and assigned responsibility.','maturity_4'=>'Automated regulatory intelligence with AI-driven impact analysis, automated control updates, and proactive compliance positioning.','control_examples'=>'Examples: Regulatory change monitoring subscriptions, Impact assessment records, Compliance update log, Regulatory intelligence reports.','sort_order'=>7],
    ['ref'=>'CMP-08','question'=>'Is the organization compliant with applicable privacy regulations (GDPR, CCPA, HIPAA) with documented evidence?','guidance'=>'Verify specific compliance measures for each applicable privacy regulation including data subject rights, consent, DPA, DPIA, and breach notification.','maturity_1'=>'No privacy regulation compliance measures in place.','maturity_2'=>'Some privacy measures exist but compliance gaps remain and documentation is incomplete.','maturity_3'=>'Documented compliance with all applicable privacy regulations including DPIAs, consent management, DSAR procedures, and DPA.','maturity_4'=>'Privacy-by-design embedded in all processes with automated compliance verification and continuous privacy risk monitoring.','control_examples'=>'Examples: Privacy compliance documentation by regulation, DPIA records, Consent management evidence, DSAR fulfillment logs.','sort_order'=>8],
    ['ref'=>'CMP-09','question'=>'Are industry-specific compliance requirements (PCI DSS, HIPAA, SOX, CMMC) addressed with appropriate controls and evidence?','guidance'=>'Verify compliance programs exist for each applicable industry standard with mapped controls, evidence collection, and certification/attestation maintenance.','maturity_1'=>'No industry-specific compliance programs despite applicable requirements.','maturity_2'=>'Some compliance activities exist but programs are incomplete or evidence is insufficient.','maturity_3'=>'Complete compliance programs for each applicable standard with mapped controls, evidence repositories, and maintained certifications.','maturity_4'=>'Integrated compliance management with unified control framework, automated evidence collection, and continuous certification readiness.','control_examples'=>'Examples: PCI DSS SAQ/ROC, HIPAA risk assessment, SOX control testing evidence, CMMC assessment records, Certification documentation.','sort_order'=>9],
],

]; // End of unified questions
